window.ARTICLES_L10N=window.ARTICLES_L10N||{};window.ARTICLES_L10N["ko"]={"a-n5-1":{"title":"나의 하루","topic":"일상","trans":["저는 매일 아침 6시에 일어나요. 세수를 하고 아침을 먹어요.","7시 반에 집을 나와서 전철을 타고 회사에 가요. 일은 9시부터 시작해요.","점심에는 회사 근처 가게에서 라멘을 먹어요. 정말 맛있어요.","저녁 6시에 일이 끝나요. 집에 돌아와서 저녁을 만들어요.","밤에는 일본어를 조금 공부하고 11시에 자요.","주말에는 일이 거의 없어요. 친구와 공원을 산책하거나 영화를 보거나 해요.","바쁜 매일이지만 일본어가 조금씩 늘어서 기뻐요."],"vocab":["일어나다","얼굴","회사","낮, 점심","만들다"],"grammar":[{"t":"に(시간)","note":"시각을 나타내는 말에는 「に」를 붙여요: 六時に、十一時に。「毎朝」는 상대적인 시간 표현이라 に를 붙이지 않아요."},{"t":"で(교통수단/장소)","note":"교통수단에는 で를 써요: 電車で。동작이 이루어지는 장소에도 で를 써요: 店で食べる。"},{"t":"て형 연결","note":"동작을 차례로 이어서 말할 때는 て형을 써요: 顔を洗って、朝ごはんを食べます。"}]},"a-n5-2":{"title":"일본의 아침 식사","topic":"문화","trans":["일본의 전통적인 아침 식사는 밥과 된장국이에요.","그 밖에 구운 생선이나 달걀도 자주 먹어요. 김도 인기가 있어요.","요즘은 빵과 커피로 아침을 먹는 사람도 많아요. 특히 젊은 사람들이 좋아해요.","바쁜 아침에는 주먹밥만 먹는 사람도 있어요. 여러분 나라의 아침 식사는 무엇인가요?","빵과 커피로 먹는 아침도 인기가 있지만, 저는 역시 밥과 된장국이 좋아요.","아침에 든든히 먹으면 하루를 기운차게 보낼 수 있어요."],"vocab":["전통적","굽다","인기","젊다","바쁘다"],"grammar":[{"t":"や(부분 나열)","note":"대표적인 것 몇 가지를 들어 그 밖에도 더 있음을 나타내요: 魚や卵、パンやコーヒー。"},{"t":"だけ","note":"'~만, ~뿐'이라는 뜻이에요: おにぎりだけ = 주먹밥만."},{"t":"が人気があります","note":"'~이/가 인기가 있다'는 뜻이에요. 대상에는 が를 써요."}]},"a-n4-3":{"title":"고도 교토를 걷다","topic":"여행","trans":["교토는 천 년도 더 전에 일본의 수도였던 도시예요. 지금도 오래된 절과 신사가 많이 남아 있어요.","봄에는 벚꽃, 가을에는 단풍이 아주 아름다워서 계절마다 다른 모습을 보여 줘요. 그래서 몇 번을 찾아도 질리지 않아요.","교토를 여행할 때는 서두르지 않고 천천히 걷는 것을 추천해요. 좁은 길로 접어들면 조용한 절이나 옛 모습 그대로인 찻집을 만날 수 있어요.","유명한 관광지뿐만 아니라 현지 사람들이 다니는 작은 가게도 둘러보면, 교토의 진짜 매력이 보일 거예요.","교토는 계절마다 다른 모습을 보여 줘요. 봄에는 벚꽃, 가을에는 단풍이 아주 아름다워요.","오래된 건물을 지키면서 새로운 문화도 받아들이는 점이 바로 교토의 매력이에요."],"vocab":["수도","남다, 남아 있다","방문하다","(길을) 돌다, 꺾다","매력"],"grammar":[{"t":"~ごとに","note":"「~마다」: 季節ごとに=계절마다."},{"t":"~ても(양보)","note":"「~해도」: 何度訪れてもあきない(몇 번을 찾아도 질리지 않는다)."},{"t":"~だけでなく","note":"「~뿐만 아니라」: 観光地だけでなく、小さな店も(관광지뿐만 아니라 작은 가게도)."}]},"a-n3-1":{"title":"편의점의 편리함","topic":"생활","trans":["일본의 편의점은 24시간 열려 있어서 아주 편리해요.","음식이나 음료뿐만 아니라 잡지와 생활용품도 살 수 있어요. 게다가 공과금 납부나 택배 발송도 할 수 있어요.","은행 ATM도 있어서 언제든지 돈을 찾을 수 있어요. 복사나 티켓 예매를 할 수 있는 기계도 있어요.","이런 서비스 덕분에 편의점은 우리 생활에 없어서는 안 될 존재가 되었어요.","하지만 편리함 뒤에는 24시간 일하는 사람들의 고생과 음식물 폐기 같은 문제도 숨어 있어요.","편리함을 당연하게 여기지 말고, 이 시스템을 뒷받침하는 사람들도 생각해 보고 싶어요."],"vocab":["편리","지불, 납부","발송","없어서는 안 되는","존재"],"grammar":[{"t":"~だけでなく","note":"「~뿐만 아니라」."},{"t":"~ので","note":"「~해서, ~니까」, 비교적 객관적이고 부드러운 표현: ATM があるので(ATM이 있어서)."},{"t":"~おかげで","note":"「~덕분에」, 긍정적인 원인: サービスのおかげで(서비스 덕분에)."}]},"a-n2-1":{"title":"일하는 방식의 변화","topic":"사회","trans":["최근 몇 년간 인터넷이 발달하면서 일하는 방식이 크게 달라졌어요.","회사에 가지 않고 집에서 일하는 「テレワーク」(재택근무)를 도입하는 기업이 늘고 있어요. 출퇴근 시간이 줄어드는 한편, 일과 생활의 구분이 어려워진다는 문제도 있어요.","또한 정해진 시간이 아니라 스스로 시간을 조정해서 일하는 사람도 많아졌어요.","이러한 변화에 맞춰 우리도 새로운 일하는 방식을 생각해 나갈 필요가 있겠죠.","재택근무가 보급되면서 일하는 장소와 시간의 자유도가 높아진 한편, 일과 생활의 경계가 모호해지는 과제도 생겨났어요.","앞으로는 사람마다 자신에게 맞는 일하는 방식을 선택할 수 있는 사회가 필요해요."],"vocab":["발달","도입하다, 받아들이다","구별","조정","필요"],"grammar":[{"t":"~にともなって","note":"'~에 따라, ~와 함께'라는 뜻으로, 함께 변화하는 상황을 나타내요. 예: 発達にともなって。"},{"t":"一方で","note":"'한편'이라는 뜻으로, 두 가지 측면을 대비할 때 써요."},{"t":"~ていく","note":"'~해 나가다'라는 뜻으로, 앞으로 계속되는 것을 나타내요. 예: 考えていく必要がある。"}]},"a-n2-2":{"title":"「空気を読む」라는 것","topic":"문화","trans":["일본어에는 「空気を読む」(분위기를 읽다)라는 표현이 있어요. 그 자리의 분위기나 상대방의 마음을 헤아려서, 분명하게 말하지 않아도 적절하게 행동하는 것을 가리켜요.","예를 들어 회의에서 모두가 찬성하는 가운데 한 사람만 반대 의견을 말하려면 용기가 필요해요. 많은 사람들은 「空気を読んで」 일부러 발언을 삼가게 돼요.","이런 감각은 사람과 사람 사이의 충돌을 피하고 집단의 조화를 지키는 데 도움이 되어 왔어요. 하지만 그 반면에 정말 필요한 의견을 말하지 못하게 되거나 소수의 목소리가 묻혀 버리기도 하는 문제가 있어요.","분위기를 읽는 능력은 분명 일본 사회의 특징 중 하나예요. 하지만 때로는 분위기를 읽지 않고 목소리를 내는 용기도 소중하게 여겨져야 하지 않을까요?","분위기를 읽는 것은 상대를 배려하는 다정함이 되기도 하지만, 지나치면 자신의 의견을 말하지 못하게 돼요.","중요한 것은 주변에 맞추는 것과 자신의 생각을 전하는 것 사이의 균형일 거예요."],"vocab":["분위기","헤아리다, 눈치채다","충돌","조화","특징"],"grammar":[{"t":"~うえで","note":"'~하는 데 있어서'라는 뜻이에요. 예: 調和を保つうえで役立つ。"},{"t":"その反面","note":"'그 반면, 반대로'라는 뜻이에요. 예: 役立つ。その反面、問題もある。"},{"t":"~べきではないだろうか","note":"'~해야 하지 않을까'라는 뜻으로, 완곡하게 주장할 때 써요. 예: 大切にされるべきではないか。"}]},"a-n3-2":{"title":"자취 생활에서 배운 것","topic":"생활","trans":["대학에 들어가서 처음으로 자취를 시작했다. 처음에는 자유로워져서 기뻤다.","하지만 막상 살아 보니 요리도 빨래도 청소도 전부 직접 해야 한다. 지금까지 부모님이 해 주셨던 일이 얼마나 많았는지 새삼 깨닫게 되었다.","돈을 쓰는 방식도 생각하게 되었다. 한정된 생활비 안에서 무엇이 정말 필요한지 자연스럽게 판단하게 된다.","자취는 힘든 점도 많지만, 자기 일을 스스로 해내는 힘이 생긴다. 그리고 무엇보다 가족의 소중함을 예전보다 훨씬 잘 알게 되었다.","혼자 있으면 외로울 때도 있지만, 그만큼 자기 시간을 자유롭게 쓸 수 있다.","가족의 소중함을 깨달은 것도 떨어져서 살기 시작하고 나서였다."],"vocab":["자취, 혼자 살기","빨래","새삼, 다시","판단","고맙다, 감사하다"],"grammar":[{"t":"~てみると","note":"'실제로 ~해 보니(알게 되었다)': 暮らしてみると."},{"t":"~なければならない","note":"'~해야 한다' 의무: 自分でやらなければならない."},{"t":"~ようになる","note":"'~하게 되다' 자연스러운 변화: 考えるようになった."}]},"a-n3-3":{"title":"센토라는 문화","topic":"문화","trans":["센토란 여러 사람이 함께 들어가는 공중목욕탕을 말해요. 옛날에는 집에 욕실이 없는 사람이 많아서 센토는 생활에 꼭 필요한 곳이었어요.","가정에 욕실이 보급되자 센토의 수는 점점 줄어들었어요. 하지만 최근 그 좋은 점이 재평가되고 있어요.","넓은 욕조에 느긋하게 몸을 담그면 몸뿐만 아니라 마음도 풀려요. 옆에 앉은 모르는 사람과 자연스럽게 대화가 이어지기도 해요.","편리함을 쫓은 나머지 우리는 사람들과의 유대를 잃어 가고 있는지도 몰라요. 센토는 그런 시대에 사람과 사람 사이의 거리를 다시 떠올리게 해 주는 곳이에요.","센토는 단순히 몸을 씻는 곳이 아니라 지역 사람들이 얼굴을 마주하는 장소이기도 했어요.","집집마다 욕실이 생긴 지금은 그 수가 줄고 있지만, 그 따뜻함을 다시 보게 된 사람도 많아요."],"vocab":["공공","보급되다, 퍼지다","다시 보다, 재평가하다","유대, 관계","거리"],"grammar":[{"t":"~とは","note":"'~란(~이다)' 정의할 때: 銭湯とは~のことだ."},{"t":"~ていく","note":"'~해 가다' 변화의 흐름: 減っていった."},{"t":"~つつある","note":"'~하고 있는 중이다' 문어체: 失いつつある."}]},"a-n4-1":{"title":"꽃구경(お花見)","topic":"문화","trans":["봄이 되면 일본 곳곳에서 벚꽃이 피어요.","사람들은 공원에 모여 벚꽃 아래에서 도시락을 먹거나 술을 마셔요. 이것을 「お花見」라고 해요.","벚꽃은 아주 예쁘지만 피어 있는 기간은 일주일 정도로 짧아요. 그래서 모두 이 시기를 기다려요.","밤에 조명을 밝힌 벚꽃도 아름다워요. 꼭 한번 보러 가 보세요.","꽃구경 풍습은 예로부터 있었고, 옛날 사람들도 벚꽃을 보며 봄을 즐겼어요.","다만 자리 맡기나 쓰레기 문제도 있어서 매너를 지키는 것이 중요해요."],"vocab":["(꽃이) 피다","모이다","기간","기대, 즐거움","아름답다"],"grammar":[{"t":"~と(항상 성립하는 조건)","note":"「~하면 ~해요」처럼 자연스럽게 이어지는 결과를 나타내요: 春になると、桜が咲く。"},{"t":"~たり~たり","note":"대표적인 동작을 나열하고, 그 밖에도 더 있음을 암시해요: 食べたり飲んだりする。"},{"t":"~てみる","note":"시험 삼아 해 본다는 뜻이에요: 行ってみてください。"}]},"a-n4-2":{"title":"전철 안 매너","topic":"생활","trans":["일본의 전철 안은 아주 조용해요. 많은 사람이 책을 읽거나 스마트폰을 보거나 눈을 감고 쉬고 있어요.","전철 안에서 전화를 하는 것은 매너 위반이라고 여겨져요. 통화하고 싶을 때는 역에서 내린 뒤에 걸어요.","또 노약자석 근처에서는 휴대전화 전원을 끄라는 안내를 받기도 해요. 심장 박동 조율기 등에 영향을 줄 수도 있기 때문이에요.","이런 매너의 배경에는 「주위 사람에게 폐를 끼치지 않는다」라는 일본의 사고방식이 있어요. 규칙이라기보다는 서로에 대한 배려예요.","이런 매너는 많은 사람이 기분 좋게 전철을 이용하기 위한 거예요.","자신뿐 아니라 주위 사람도 생각하면 모두가 쾌적하게 지낼 수 있어요."],"vocab":["조용하다","위반","노약자석","영향","배려"],"grammar":[{"t":"~たり~たり","note":"동작을 나열해요: 読んだり、見たり、休んだり。"},{"t":"~ように言われる","note":"~하라는 말을 듣다, 요청받다: 電源を切るように言われる。"},{"t":"~という(명사 수식 인용)","note":"「~という考え方」처럼 내용이나 이름을 가리킬 때 써요."}]},"a-n3-4":{"title":"진행되는 저출산","topic":"뉴스","trans":["일본에서는 지금 아이의 수가 계속 줄고 있어요. 이를 「少子化」(저출산)라고 불러요.","원인은 하나가 아니에요. 결혼하지 않는 사람이 늘어난 것, 아이를 키우는 데 드는 돈의 부담이 큰 것, 일과 육아를 병행하기 어려운 것 등 여러 이유가 겹쳐 있어요.","아이가 줄면 앞으로 일할 사람의 수도 줄어요. 그 결과 경제력이 약해지거나, 노인을 지원하는 제도가 유지되지 못할 우려가 있어요.","정부는 여러 대책을 추진하고 있지만 효과는 아직 충분하지 않아요. 사회 전체가 아이를 키우기 좋은 환경을 어떻게 만들 것인지가 과제로 떠오르고 있어요.","저출산의 배경에는 결혼과 육아에 드는 부담이 크다는 점이 있다고 해요.","이대로 가면 일하는 사람이 줄어서 사회 전체를 떠받치기가 어려워져요."],"vocab":[{"w":"減る","m":"줄다, 감소하다"},{"w":"負担","m":"부담"},{"w":"両立","m":"양립, 병행"},{"w":"支える","m":"떠받치다, 지탱하다"},{"w":"対策","m":"대책"}],"grammar":[{"t":"~続ける","note":"「계속 ~하다」: 減り続けている。"},{"t":"~たり~たりする","note":"가능한 상황을 나열할 때 써요: 弱くなったり、立ちゆかなくなったり。"},{"t":"~おそれがある","note":"「~할 위험/우려가 있다」 부정적인 내용에 써요: 立ちゆかなくなるおそれがある。"}]},"a-n3-5":{"title":"술자리 소통 문화","topic":"직장","trans":["일본 회사에서는 퇴근 후에 동료나 상사와 술을 마시러 가는 일이 자주 있어요. 이를 「飲みニケーション」이라고 해요.","술자리에서는 평소에 말하기 어려운 속마음을 털어놓거나 상사와 편하게 이야기할 수 있어요. 인간관계를 깊게 하는 좋은 기회라고 생각하는 사람도 많아요.","한편 젊은 세대 중에는 「퇴근 후 시간은 나를 위해 쓰고 싶다」라고 생각하는 사람이 늘고 있어요. 참석을 강요당하는 데 거부감을 느끼는 사람도 적지 않아요.","일하는 방식과 가치관이 다양해진 지금, 술자리 소통의 모습도 조금씩 변해 가고 있는지도 몰라요.","하지만 요즘 젊은 사람들 중에는 일과 사생활을 확실히 구분하고 싶어 하는 사람도 늘고 있어요.","술에 기대지 않아도 평소 대화로 신뢰를 쌓을 수 있는 것이 이상적이겠지요."],"vocab":[{"w":"同僚","m":"동료"},{"w":"本音","m":"속마음, 본심"},{"w":"気軽","m":"부담 없음, 편안함"},{"w":"強制","m":"강제, 강요"},{"w":"多様","m":"다양함"}],"grammar":[{"t":"~にくい","note":"「~하기 어렵다」: 言いにくい。"},{"t":"一方で","note":"「한편」 대비를 나타내요: ~という人も多い。一方で、~。"},{"t":"~つつある","note":"「점점 ~해 가고 있다」: 変わりつつある。"}]},"a-n5-3":{"title":"가족 사진","topic":"가족","trans":["이것은 우리 가족의 사진이에요. 모두 다섯 명이 있어요.","가운데에 있는 사람은 아버지와 어머니예요. 아버지는 회사원이고, 어머니는 선생님이에요.","오른쪽에 있는 사람은 형(오빠)이에요. 형(오빠)은 대학생이고, 축구를 아주 잘해요.","왼쪽의 작은 아이는 여동생이에요. 여동생은 아홉 살이고, 그림 그리기를 좋아해요.","우리 가족은 모두 강아지를 아주 좋아해요. 사진 앞에 있는 아이가 우리 집 강아지 「マロ」예요.","쉬는 날에는 자주 다 같이 공원에 가서 사진을 찍어요.","떨어져 살지만, 한 달에 한 번은 전화로 이야기해요. 가족은 제 보물이에요."],"vocab":["가족","회사원","대학생","좋아하다","보물"],"grammar":[{"t":"〜で(나열)","note":"명사＋で로 두 문장을 이어 줄 수 있어요. 「ちちは会社員で、ははは先生です」처럼 나란히 설명할 때 써요."},{"t":"〜が(대상)","note":"능력이나 좋고 싫음의 대상에는 が를 써요. 「サッカーが上手」「犬が好き」처럼요."},{"t":"〜のが","note":"동사＋のが는 동작을 명사처럼 만들어 줘요. 「絵をかくのが好き」(그림 그리는 것을 좋아해요)처럼 써요."}]},"a-n5-4":{"title":"편의점에서 쇼핑","topic":"생활","trans":["저는 매일 편의점에 가요. 회사 바로 옆에 있어서 아주 편리해요.","아침에는 주먹밥과 커피를 사요. 모두 합쳐서 300엔 정도예요.","편의점에서는 전기요금이나 수도요금도 낼 수 있어요.","택배를 보내거나 돈을 찾을 수도 있어요.","밤에 배가 고플 때는 따뜻한 오뎅을 사요. 겨울에는 특히 인기가 많아요.","요즘은 외국어 안내도 많아서 외국에서 온 사람에게도 친절해요.","작은 가게지만 여러 가지 일을 할 수 있어서 일본 생활에 없어서는 안 될 존재예요."],"vocab":["편리하다","내다, 지불하다","보내다, 내놓다","인기","생활"],"grammar":[{"t":"〜ことができる","note":"동사 사전형＋ことができる는 능력이나 가능을 나타내요. 「はらうことができる」(낼 수 있다)처럼 써요."},{"t":"〜たり〜たりする","note":"여러 동작을 예로 들어 나열할 때 써요. 「出したり、おろしたりする」(보내기도 하고 찾기도 한다)처럼요."},{"t":"〜ので","note":"객관적인 이유에는 ので를 써요. 「となりにあるので、べんりです」(옆에 있어서 편리해요)처럼요."}]},"a-n2-3":{"title":"보고·연락·상담","topic":"직장","trans":["일본 회사에 들어가면 가장 먼저 「報連相(ほうれんそう)」의 중요성을 배워요. 보고·연락·상담의 첫 글자를 따서 만든 말이에요.","업무 진행 상황을 상사에게 「보고」하고, 관련된 사람에게 필요한 정보를 「연락」하고, 판단이 망설여질 때는 일찍 「상담」해요. 이것을 할 수 있느냐 없느냐에 따라 일이 풀리는 방식이 크게 달라져요.","문제를 혼자 끌어안고 보고가 늦어지면 작은 실수가 큰 문제로 번질 수도 있어요. 반대로 정보를 틈틈이 공유하면 주변 사람들이 빨리 도와줄 수 있어요.","보고·연락·상담은 단순한 규칙이 아니에요. 팀으로 일할 때 서로의 신뢰를 쌓기 위한 기본적인 소통이에요.","보고·연락·상담이 잘 이루어지지 않는 직장에서는 작은 실수가 큰 문제로 번지기 쉬워요.","반대로 정보를 꼼꼼히 공유하면 팀 전체의 신뢰와 효율이 높아져요."],"vocab":[{"w":"具合","m":"상태, 상황"},{"w":"迷う","m":"망설이다, 헤매다"},{"w":"抱え込む","m":"혼자 떠안다"},{"w":"信頼","m":"신뢰"},{"w":"築く","m":"쌓다, 구축하다"}],"grammar":[{"t":"~かどうか","note":"'~인지 아닌지'를 나타내는 간접 의문이에요: できるかどうかで変わる。"},{"t":"~かねない","note":"'~할 수도 있다(좋지 않은 일)': トラブルに発展しかねない。"},{"t":"~うえで","note":"'~하는 데 있어서': チームで働くうえで。"}]},"a-n2-4":{"title":"오버투어리즘을 생각하다","topic":"여행","trans":["최근 인기 있는 관광지에는 국내외에서 많은 여행객이 몰려들고 있어요. 관광은 지역에 큰 이익을 가져다주는 한편, 「관광 공해」라고 불리는 문제도 낳고 있어요.","예를 들어 길이 관광객으로 넘쳐 주민이 지나다니지 못하게 되거나, 쓰레기와 매너 위반이 늘어나요. 조용히 살아가던 사람들의 생활이 위협받게 되는 거예요.","이런 문제에 대응해 입장 인원을 제한하거나 관광세를 도입하는 지역도 나타났어요. 하지만 규제를 지나치게 강화하면 관광 자체의 매력이 사라질 수도 있어요.","중요한 것은 방문하는 쪽이 현지에 대한 존중을 잊지 않는 것이겠지요. 그 지역의 문화와 규칙을 존중해야만 관광이 여행객과 주민 모두에게 풍요로운 것이 되지 않을까요?","관광은 지역에 돈을 가져다주는 한편, 주민의 생활을 위협하기도 해요.","방문하는 사람과 사는 사람 모두가 편안하게 지낼 수 있는 구조를 만드는 일이 지금 요구되고 있어요."],"vocab":[{"w":"押し寄せる","m":"밀려들다, 몰려들다"},{"w":"利益","m":"이익"},{"w":"脅かす","m":"위협하다"},{"w":"制限","m":"제한"},{"w":"尊重","m":"존중"}],"grammar":[{"t":"~に対して","note":"'~에 대해, ~에 대응하여': 問題に対して。"},{"t":"~かねない","note":"'~할 수도 있다(좋지 않은 일)': 失われかねない。"},{"t":"~てこそ","note":"'~해야만 비로소': 尊重してこそ豊かになる。"}]},"a-n5-5":{"title":"나의 마을","topic":"생활","trans":["저는 작은 마을에 살고 있어요. 바다 근처에 있어서 공기가 깨끗해요.","마을에는 큰 빌딩은 없지만 우체국과 병원, 슈퍼마켓이 있어요.","역에서 집까지 걸어서 10분쯤 걸려요. 가는 길에 강이 있어서 다리를 건너요.","봄에는 강가의 벚꽃이 아주 예뻐서 많은 사람이 꽃구경을 하러 와요.","근처에 오래된 절이 있는데, 조용하고 마음이 편안해져요.","쇼핑하기에는 조금 불편하지만 모두 친절해서 살기 좋은 마을이에요.","저는 이 마을이 정말 좋아요. 계속 여기에서 살고 싶어요."],"vocab":["살다, 거주하다","근처, 가까운 곳","건너다","친절하다","조용하다"],"grammar":[{"t":"〜やすい","note":"동사 ます형＋やすい는 '~하기 쉽다'라는 뜻이에요. 「すみやすい」는 '살기 편하다'예요."},{"t":"〜たい","note":"동사 ます형＋たい는 희망을 나타내요. 「住みたい」는 '살고 싶다'예요."},{"t":"〜が(逆接)","note":"「ふべんですが、しんせつです」처럼 앞뒤 내용이 반대일 때 が를 써요. 한국어의 '~지만'과 비슷해요."}]},"a-n4-4":{"title":"처음으로 떠난 혼자 여행","topic":"여행","trans":["지난달에 처음으로 혼자 여행을 갔어요. 목적지는 전부터 궁금했던 가나자와예요.","출발 전에는 조금 불안했지만, 직접 계획을 세우는 일이 생각보다 즐거웠어요.","아침 일찍 신칸센을 타고 점심때가 지나 가나자와에 도착했어요. 역이 아주 커서 깜짝 놀랐어요.","먼저 유명한 정원을 보러 갔어요. 날씨가 좋아서 사진을 많이 찍었어요.","밤에는 시장에서 신선한 해산물을 먹었어요. 혼자라서 먹고 싶은 것을 먹고 싶은 만큼 주문할 수 있었어요.","낯선 도시를 혼자 걷는 것은 조금 쓸쓸했지만, 자유롭고 아주 기분이 좋았어요.","이번 여행으로 혼자서도 어떻게든 된다는 자신감이 생겼어요. 또 가고 싶어요."],"vocab":["혼자 하는 여행","계획을 세우다","신선하다","자유","자신감"],"grammar":[{"t":"〜より","note":"「思ったより楽しい」처럼 '~보다 더 ~하다'라는 뜻으로, 예상보다 더하다는 걸 나타내요."},{"t":"〜だけ","note":"「好きなだけ注文できる」처럼 어떤 한도까지를 나타내요. '원하는 만큼'이라는 뜻이에요."},{"t":"〜という〜","note":"「何とかなるという自信」처럼 という로 뒤에 오는 명사의 내용을 설명해요. 한국어의 '~라는'과 비슷해요."}]},"a-n1-1":{"title":"지구 온난화와 우리의 생활","topic":"환경","trans":["지구 온난화는 더 이상 먼 미래의 이야기가 아니라, 우리의 생활에 직접 영향을 미치는 문제가 되었어요.","이상 기후로 인한 농작물 피해와 해수면 상승에 따른 재해는 해마다 더 심각해지고 있어요. 이런 상황 앞에서는 한 사람이 할 수 있는 일이 한정되어 있다고 느낄지도 몰라요.","하지만 전기 낭비를 줄이거나 대중교통을 이용하는 것 같은 작은 실천이 쌓여야 비로소 큰 변화로 이어져요.","미래 세대에게 풍요로운 지구를 남겨 주기 위해서라도, 지금 행동에 나서는 것이 필요해요.","온난화는 먼 나라의 이야기가 아니라, 우리의 식탁과 생활에 직접 관련된 문제예요.","한 사람 한 사람의 작은 행동이 쌓여 결국 큰 변화를 만든다는 사실을 잊어서는 안 돼요."],"vocab":["미치다, 영향을 끼치다","피해","심각하다","쌓아 가기, 축적","세대"],"grammar":[{"t":"~ばかりだ","note":"「계속 ~하기만 한다, 점점 ~해진다」 한 방향으로만 진행되는 변화를 나타내요: 深刻さを増すばかりだ。"},{"t":"~こそ","note":"「바로 ~이야말로」 강조를 나타내요: 積み重ねこそが変化につながる。"},{"t":"~ためにも","note":"「~하기 위해서라도」: 世代に残すためにも行動を。"}]},"a-n1-2":{"title":"AI 시대에 다시 묻는 '배움'의 의미","topic":"뉴스","trans":["생성형 AI가 빠르게 보급되면서 지식을 얻는 문턱은 유례없이 낮아졌어요. 궁금한 점이 있으면 물어보기만 해도 AI가 순식간에 답을 알려 줘요.","이런 상황에서 '이제 사람이 애써 배울 필요는 없는 것 아니냐'는 목소리도 들리기 시작했어요. 하지만 그것은 배움이라는 행위의 본질을 잘못 보고 있는 것처럼 느껴져요.","배움이란 단순히 답을 손에 넣는 것이 아니에요. 정보가 올바른지 가려내고, 여러 생각을 비교하고, 나름의 판단을 내리는 것, 바로 그 과정에서 생각하는 힘이 길러져요. AI가 내놓은 답을 비판적으로 따져 볼 수 있는지는 바로 그 사람이 배운 깊이에 달려 있어요.","답을 쉽게 얻을 수 있는 시대이기 때문에 '왜 그런가'를 계속 묻는 자세가 이전보다 더 중요해졌어요. 배움의 의미는 사라지기는커녕 오히려 다시 질문받고 있어요.","AI가 답을 바로 내놓는 시대이기 때문에 '왜 그런가'를 계속 묻는 자세가 한층 더 중요해져요.","지식을 쌓아 두는 것보다 그것을 어떻게 활용하고 어떻게 판단하느냐가 앞으로 배움의 중심이 될 거예요."],"vocab":["보급","본질","간파하다, 가려내다","면밀히 따져 봄","다시 묻다, 재검토하다"],"grammar":[{"t":"~により","note":"「~로 인해, ~을 통해」: 普及により、低くなった。"},{"t":"~どころか","note":"「~은커녕, ~하기는커녕 오히려」: 失われるどころか、問い直されている。"},{"t":"~からこそ","note":"「~이기 때문에 더욱」: 時代だからこそ、重要になっている。"}]},"a-n4-5":{"title":"아르바이트 하루","topic":"일","trans":["저는 대학에 다니면서 카페에서 아르바이트를 해요. 일주일에 세 번, 저녁부터 밤까지 근무해요.","가게에 도착하면 먼저 유니폼으로 갈아입고 손을 깨끗이 씻어요.","하는 일은 주문 받기, 커피 만들기, 테이블 정리하기 같은 것들이에요.","바쁜 시간에는 정말 힘들지만, 손님이 「ありがとう」라고 말해 주면 피로가 싹 날아가요.","처음에는 실수투성이라서 선배에게 자주 주의를 받았어요. 하지만 조금씩 할 수 있는 일이 늘었어요.","아르바이트 덕분에 돈뿐만 아니라 사람과 대화하는 방법과 팀워크의 중요성도 배웠어요.","공부와 병행하는 것은 쉽지 않지만, 사회에 나가기 전에 좋은 경험이 되고 있다고 생각해요."],"vocab":["다니다, (학교·직장에) 다니다","옷을 갈아입다","정리하다, 치우다","선배","경험"],"grammar":[{"t":"〜ながら","note":"동사 ます형＋ながら는 두 가지 일을 동시에 한다는 뜻이에요. 「通いながら働く」(다니면서 일하다)."},{"t":"〜ばかり","note":"「失敗ばかり」는 '실수만 한다', '계속 ~하기만 한다'는 뜻이에요."},{"t":"〜おかげで","note":"「アルバイトのおかげで」처럼 좋은 결과의 원인을 나타내요. '덕분에'라는 뜻이에요."}]},"a-n3-6":{"title":"일본의 사계절과 연중행사","topic":"문화","trans":["일본에는 봄, 여름, 가을, 겨울의 네 계절이 있고, 계절마다 어울리는 행사를 지금도 소중히 여겨요.","봄은 벚꽃의 계절이에요. 사람들은 공원에 모여 꽃 아래에서 식사를 하며 봄이 오는 것을 축하해요.","여름이 되면 각지에서 마쓰리와 불꽃놀이 축제가 열리고, 유카타를 입은 사람들로 북적여요.","가을은 「식욕의 가을」, 「독서의 가을」이라고도 불리며, 선선해진 공기 속에서 단풍을 즐기는 사람이 많아요.","겨울에는 설날이 있어요. 가족이 모여 오세치 요리를 먹고 신사에 하쓰모데를 하러 가는 것이 일반적이에요.","이런 행사는 계절의 변화를 느끼고 가족이나 지역 사람들과의 유대를 확인하는 기회가 되고 있어요.","편리한 생활 속에서도 자연의 리듬을 소중히 여기는 마음은 앞으로도 계속 이어질 거예요."],"vocab":["계절","행사, 기념일","축하하다","일반적","이어받다, 계승하다"],"grammar":[{"t":"〜に合わせて","note":"「季節に合わせた行事」처럼 어떤 것에 맞춘다는 뜻이에요. '~에 맞춰서'로 옮겨요."},{"t":"〜と言われる","note":"「食欲の秋と言われる」는 일반적으로 그렇게 말한다, 즉 '~라고 불린다'는 뜻이에요."},{"t":"〜だろう","note":"「受けつがれていくだろう」처럼 추측을 나타내요. '~일 거예요'라는 뜻이에요."}]},"a-n2-5":{"title":"확산되는 캐시리스 결제","topic":"사회","trans":["최근 몇 년 사이 일본에서도 캐시리스 결제가 빠르게 퍼지고 있어요. 예전에는 현금만 쓸 수 있는 가게가 많았지만, 지금은 스마트폰이나 카드로 결제할 수 있는 가게가 늘고 있어요.","캐시리스 결제는 결제가 빠르고 돈 관리가 쉽다는 장점이 있어요. 계산대에서 동전을 찾을 필요가 없고, 언제 얼마를 썼는지가 기록으로 남기 때문이에요.","한편 과제도 남아 있어요. 정전이나 통신 장애가 일어나면 결제를 할 수 없게 될 우려가 있어요. 과소비하는 사람이나 기기 조작이 서툰 고령자에 대한 배려도 빼놓을 수 없어요.","편리함과 안심 사이의 균형을 어떻게 잡을까요? 현금과 캐시리스가 잘 공존할 수 있는 사회가 요구되고 있어요."],"vocab":["결제, 지불","빠르게, 급속히","현금","지불하다","장점","동전, 잔돈","기록","과제, 해결해야 할 문제","정전","통신 장애","우려, 위험","배려","공존","요구하다, 구하다"],"grammar":[{"t":"〜てくる(변화)","note":"「広がってきた」는 지금까지 이어져 온 변화나 추세를 나타내요."},{"t":"〜恐れがある","note":"「できなくなる恐れがある」는 (좋지 않은) 가능성이 있다는 뜻이에요."},{"t":"一方(で)","note":"「一方で、課題も残されている」처럼 상반되는 다른 측면을 제시할 때 써요."}]},"a-n1-3":{"title":"저출산 고령화라는 난제","topic":"사회","trans":["일본은 세계적으로도 유례를 찾아볼 수 없는 속도로 저출산 고령화가 진행되고 있어요. 총인구에서 고령자가 차지하는 비율은 해마다 오르는 반면, 태어나는 아이의 수는 계속 줄고 있어요.","이런 경향이 가져올 영향은 사회보장제도의 근간을 뒤흔들 수도 있어요. 연금, 의료, 간병에 드는 비용은 늘어나는데, 이를 떠받칠 현역 세대는 줄어들기 때문이에요.","대책으로는 육아와 일의 양립을 지원하는 제도를 충실히 하는 것, 외국인 노동자 수용을 확대하는 것 등이 논의되고 있어요. 하지만 어느 쪽도 하루아침에 해결할 수 있는 문제가 아니에요.","출생률이 떨어지는 배경에는 경제적 불안과 가치관의 다양화 같은 복잡한 요인이 얽혀 있어요. 단순히 보조금을 나눠 주면 끝나는 이야기가 아니에요.","저출산 고령화는 이제 피할 수 없는 현실이에요. 사회 전체가 이를 어떻게 마주하고, 다음 세대에 어떤 나라를 물려줄 것인가. 지금이야말로 진지한 논의가 필요해요."],"vocab":["비율","경향, 추세","근간, 핵심","간병, 돌봄","양립, 병행","하루아침, 짧은 시간","출생률","요인"],"grammar":[{"t":"~かねない","note":"「~할 수도 있다(나쁜 결과)」: 根幹を揺るがしかねない=근간을 뒤흔들 수도 있다."},{"t":"~一方で","note":"두 측면을 대비해요: 費用は増える一方で、現役世代は減る。(비용은 늘어나는 한편, 현역 세대는 줄어요.)"},{"t":"~ではないのだ","note":"부정을 강조하거나 결론을 내릴 때 써요: 済むという話ではないのだ。"}]},"a-n1-6":{"title":"이어받는 것","topic":"문화","trans":["각지에 전해 내려오는 전통문화와 장인의 기술은 오랜 세월에 걸쳐 갈고닦이고 이어져 온 둘도 없는 자산이에요. 하지만 지금, 그중 많은 것이 존속의 위기에 처해 있어요.","가장 큰 요인은 후계자 부족이에요. 기술을 이어갈 사람들의 고령화가 계속되는 한편, 젊은이들은 도시로 빠져나가고 기술을 배우려는 사람은 해마다 줄고 있어요.","전통을 지킨다고 해도 그저 옛날 모습 그대로를 유지하면 된다는 뜻은 아니에요. 시대의 변화에 맞춰 새로운 가치를 만들어 내야만 문화는 계속 살아갈 수 있어요.","최근에는 전통 공예에 현대적인 디자인을 도입하거나 해외에 알리는 시도도 점점 넓어지고 있어요. 옛것과 새것의 융합이 활로를 여는 열쇠가 돼요.","선조들이 쌓아 온 것을 다음 세대에 어떻게 이어 줄까요? 그것은 우리 한 사람 한 사람에게 주어진 무거운 숙제일지도 몰라요."],"vocab":["장인","존속","(위기 등에) 처하다, 직면하다","후계자, 후임자","담당자, 이어갈 사람","융합","활로, 살길","선인, 선조"],"grammar":[{"t":"~てこそ","note":"'~해야만 비로소'라는 뜻이에요: 새로운 가치를 만들어 내야만 계속 살아갈 수 있어요."},{"t":"~わけではない","note":"부분 부정이에요. '~라는 뜻은 아니다': 옛날 그대로를 유지하면 된다는 뜻은 아니에요."},{"t":"~つつある","note":"'점점 ~하고 있다'라는 뜻이에요: 시도도 점점 넓어지고 있어요."}]},"a-n2-6":{"title":"잠을 소중히","topic":"건강","trans":["바쁜 나날 속에서 나도 모르게 줄이기 쉬운 것이 바로 수면 시간이에요. 하지만 질 좋은 수면은 건강한 생활을 하는 데 없어서는 안 되는 것이에요.","잠이 부족하면 집중력이 떨어지거나 몸 상태가 나빠지기도 해요. 낮에 쏟아지는 졸음 때문에 일이나 공부가 잘 안 되는 사람도 많을 거예요.","잠을 잘 자려면 먼저 생활 리듬을 가다듬는 것이 중요해요. 매일 같은 시간에 자고 같은 시간에 일어나는 습관을 들여 보세요.","또 자기 전에 스마트폰을 보는 것은 가능한 한 피하는 편이 좋아요. 화면의 밝은 빛이 뇌를 깨워 버리기 때문이에요.","겨우 몇 시간 차이라도 매일 쌓이면 큰 차이가 돼요. 우선 조금 일찍 이불에 들어가는 것부터 시작해 보지 않을래요?"],"vocab":["줄이다, 깎다","수면","없어서는 안 되는","집중력","졸음","가다듬다, 정돈하다","피하다","쌓임, 누적"],"grammar":[{"t":"~がち","note":"'~하기 쉽다, 자주 ~하다'라는 뜻이에요: 나도 모르게 줄이기 쉬워요."},{"t":"~うえで","note":"'~하는 데 있어서'라는 뜻이에요: 건강한 생활을 하는 데 없어서는 안 돼요."},{"t":"~たほうがよい","note":"권유·조언을 나타내요: 스마트폰을 보는 것은 피하는 편이 좋아요."}]},"a-n2-7":{"title":"そなえあれば","topic":"생활","trans":["일본은 지진이나 태풍 같은 자연재해가 많은 나라예요. 언제 일어날지 모르는 재해에 평소부터 대비해 두는 것이 매우 중요해요.","먼저 가정에서 할 수 있는 일부터 시작해 봐요. 물과 식량, 손전등 등을 준비해서 바로 들고 나갈 수 있는 곳에 두면 안심이 돼요.","가족과 미리 이야기해 두는 것도 잊으면 안 돼요. 만약 서로 흩어졌을 때 어디에서 모일지 정해 두면 당황하지 않고 행동할 수 있어요.","또 자신이 사는 지역의 위험한 장소를 알아 두는 것도 도움이 돼요. 시청 등에서 나눠 주는 지도를 보고 대피소까지 가는 길을 확인해 두세요.","재해는 막을 수 없더라도 피해를 줄일 수는 있어요. 평소의 사소한 마음가짐이 만일의 순간에 나와 가족을 지켜 줘요."],"vocab":["재해","대비하다, 준비하다","손전등","들고 나갈 수 있다, 꺼낼 수 있다","대피소","피해","마음가짐, 유의","지키다, 보호하다"],"grammar":[{"t":"~ておく","note":"미리 해 두는 것을 나타내요: 備えておく(대비해 두다), 決めておく(정해 두다)."},{"t":"~てはいけない","note":"금지·불가를 나타내요: 話し合っておくことも忘れてはいけない(미리 이야기해 두는 것도 잊으면 안 된다)."},{"t":"いざというとき","note":"'만일의 순간, 긴급한 때'라는 뜻의 관용 표현이에요: いざというときに守る(만일의 순간에 지켜 준다)."}]},"a-n5-6":{"title":"わたしの しゅみ","topic":"취미","trans":["제 취미는 사진을 찍는 거예요.","쉬는 날에는 카메라를 들고 거리를 걸어요.","꽃이나 새 사진을 찍어요.","예쁜 사진이 찍혔을 때 정말 기뻐요.","가끔 친구에게 사진을 보내요.","친구는 「じょうずですね」라고 말해요.","새 카메라를 갖고 싶지만 비싸서 지금은 돈을 모으고 있어요."],"vocab":["취미","사진","(사진을) 찍다","걷다","보내다","(돈을) 모으다"],"grammar":[{"t":"しゅみは~ことです","note":"'내 취미는 ~하는 것이에요': 명사화하는 こと로 문장을 맺어요. しゅみは しゃしんを とる ことです."},{"t":"~とき","note":"'~할 때': とれた とき(찍혔을 때)."},{"t":"~が ほしい","note":"'~을/를 갖고 싶다(물건)': カメラが ほしいです. 원하는 대상에는 が를 써요."}]},"a-n1-4":{"title":"정보의 바다를 헤엄치기 위해","topic":"미디어","trans":["스마트폰이 보급되면서 우리는 언제 어디서나 방대한 정보를 접할 수 있게 되었어요. 하지만 그 편리함 뒤에는 지나칠 수 없는 함정이 숨어 있어요.","인터넷에는 진위가 불분명한 정보가 넘쳐나요. 그중에는 악의를 가지고 퍼뜨리는 가짜 뉴스도 적지 않아요. 사실과 의견을 구분하는 능력이 전에 없이 요구되고 있어요.","더 골치 아픈 것은 내 취향에 맞는 정보만 보여 주는 시스템이에요. 나도 모르는 사이에 시야가 좁아지고, 편향된 생각에 빠지기 쉬워요.","중요한 것은 하나의 정보를 곧이곧대로 믿지 않고, 여러 정보원을 찾아보며 확인하는 자세예요. 정보를 발신할 때도 그 내용에 책임을 져야 해요.","정보를 올바르게 읽어 내는 능력은 이제 일부 전문가만의 것이 아니에요. 누구나 갖춰야 할, 현대를 살아가기 위한 필수 교양이에요."],"vocab":["보급","방대함","진위","확산, 퍼뜨림","골치 아픔, 성가심","시야","곧이곧대로 믿음, 무비판적 수용","교양, 소양"],"grammar":[{"t":"~ずにはいられない/~ないうちに","note":"「知らず知らずのうちに」=나도 모르는 사이에."},{"t":"~ばかり","note":"한정, 편중: 好みに合う情報ばかりが表示される (취향에 맞는 정보만 표시된다)."},{"t":"もはや~ない","note":"「이제는 ~가 아니다」: もはや専門家だけのものではない."}]},"a-n1-5":{"title":"버려지는 음식","topic":"사회","trans":["아직 먹을 수 있는데도 버려지는 식품, 이른바 식품 손실이 세계적인 문제가 되고 있어요. 일본에서도 해마다 수백만 톤이나 되는 식량이 쓸데없이 폐기되고 있다고 해요.","한편 세계에는 충분히 먹지 못하는 사람이 많이 있어요. 풍요의 상징처럼 보이는 포식의 이면에서 심각한 불균형이 생기고 있는 거예요.","식품 손실의 원인은 가정이나 음식점에서 나오는 잔반만이 아니에요. 아직 팔 수 있을 상품이 유통기한을 이유로 대량 처분되는 현실도 간과할 수 없어요.","이 문제를 해결하려면 기업의 노력은 물론 한 사람 한 사람의 의식 변화가 꼭 필요해요. 너무 많이 사지 않기, 너무 많이 만들지 않기 같은 마음가짐이 큰 한 걸음이 돼요.","한정된 자원을 소중히 하는 것은 다음 세대에 대한 책임이기도 해요. 음식을 낭비하지 않는 생활 방식이 지금 다시 질문받고 있어요."],"vocab":["폐기, 버림","많은 사람","포식, 풍족한 식생활","불균형","유통기한(맛있게 먹을 수 있는 기한)","처분, 처리","빼놓을 수 없음, 필수적임","자원"],"grammar":[{"t":"~のに","note":"역접: まだ食べられるのに捨てられる (아직 먹을 수 있는데도 버려진다)."},{"t":"~はもちろん","note":"「~은 물론, 말할 것도 없고」: 企業の取り組みはもちろん."},{"t":"~ずにはいられない/見逃せない","note":"「간과할 수 없다」: 現状も見逃せない."}]},"a-n4-7":{"title":"쓰레기 배출 방법","topic":"생활","trans":["일본에 살기 시작하고 나서 가장 놀란 것은 쓰레기를 내놓는 방법이에요.","쓰레기는 「燃えるごみ」「燃えないごみ」「資源ごみ」 등으로 나눠야 해요.","내놓는 요일도 정해져 있는데, 제가 사는 동네에서는 가연 쓰레기가 월요일과 목요일이에요.","아침 8시까지 정해진 장소에 내놓아야 해요.","잘못 분리하면 쓰레기를 수거해 가지 않을 때도 있어요.","처음에는 귀찮다고 생각했지만, 익숙해지면 어렵지 않아요.","분리배출 덕분에 동네는 언제나 깨끗해요."],"vocab":["놀라다","나누다, 분류하다","정해지다, 정해져 있다","착각하다, 잘못하다","귀찮음, 번거로움","익숙해지다","(쓰레기) 분리배출"],"grammar":[{"t":"~なければなりません","note":"'~해야 해요': 分けなければなりません(나눠야 해요)."},{"t":"~までに","note":"'~까지(기한)': 朝八時までに出します(아침 8시까지 내놓아요). までに는 기한을, まで는 계속되는 기간을 나타내요."},{"t":"~てもらえない","note":"'상대가 나를 위해 ~해 주지 않다': 持って行ってもらえない(수거해 가지 않다). てもらう의 가능 부정형이에요."},{"t":"~おかげで","note":"'~덕분에': 分別のおかげで、町はきれいです(분리배출 덕분에 동네는 깨끗해요)."}]},"a-n3-8":{"title":"일본에서 병원에 가기","topic":"생활","trans":["일본에서 처음 열이 났을 때, 어떻게 해야 할지 몰라서 많이 불안했어요.","친구에게 상의했더니 「먼저 가까운 내과에 가는 게 좋아」라고 알려 줬어요.","병원에서는 먼저 건강보험증을 내고, 문진표에 증상을 적어요.","「언제부터 아프세요?」「알레르기는 있으세요?」 등 묻는 내용은 대체로 정해져 있어요.","진찰이 끝나면 처방전을 받고, 약국에서 약을 받아요.","비용은 생각보다 쌌어요. 보험에 가입되어 있으면 본인이 내는 돈은 30%뿐이거든요.","언어가 걱정되는 사람은 증상을 종이에 써서 보여 주면 좋아요. 뜻을 전달할 방법은 얼마든지 있어요."],"vocab":["불안","상담, 상의","건강보험증","증상","진찰","처방전","약국","받다, 수령하다"],"grammar":[{"t":"~たほうがいい","note":"'~하는 게 좋다(조언)': 行ったほうがいい(가는 게 좋다)."},{"t":"~と(條件)","note":"'~하면 …': 相談すると、教えてくれた/診察が終わると. 앞의 일이 일어나면 뒤의 일이 자연스럽게 이어져요."},{"t":"~より","note":"'~보다': 思ったより安かった(생각보다 쌌다)."},{"t":"~といい","note":"'~하면 좋다, ~하길 권한다': 書いて見せるといい(써서 보여 주면 좋다)."}]},"a-n5-7":{"title":"우체국에서 짐 보내기","topic":"생활","trans":["오늘은 우체국에 짐을 부치러 가요.","창구에서 「これを 台湾へ おねがいします」라고 말해요.","직원이 「船便ですか、航空便ですか」라고 물었어요.","선편은 싸지만 한 달쯤 걸려요. 항공편은 빠르지만 비싸요.","저는 항공편을 골랐어요. 용지에 이름과 주소를 쓴 다음에 돈을 내요.","「いつ とどきますか」라고 묻자 「一週間ぐらいです」라고 알려 주었어요.","돌아오는 길에 편의점에서 우표를 사고 엽서도 부쳤어요."],"vocab":["우체국","짐, 소포","창구","선편(배편)","항공편","용지, 종이","주소","우표","도착하다"],"grammar":[{"t":"～てから","note":"앞의 동작을 끝낸 뒤에 뒤의 동작을 한다는 뜻이에요. 「書いてから はらいます」는 '쓴 다음에 낸다'라는 뜻으로, 순서가 분명해요."},{"t":"～と いいます／ききます","note":"말하거나 물은 내용을 인용할 때 문장 전체를 「と」 앞에 넣어요. 「これを おねがいします」と いいます."},{"t":"～に いきます(目的)","note":"동사의 ます형에서 ます를 빼고 に いきます를 붙이면 '~하러 가요'라는 뜻이에요. 「おくりに いきます」는 '부치러 가요'라는 뜻이에요."}]},"a-n4-8":{"title":"구청에서 하는 절차","topic":"생활","trans":["이사를 하면 14일 이내에 구청에 가야 해요.","창구에서 「転入届を出したいんですが」라고 말했더니 번호표를 받았어요.","이름이 불릴 때까지 의자에 앉아서 기다려요. 기다리는 동안 서류에 주소와 생년월일을 미리 써 두었어요.","담당자는 재류카드를 확인한 뒤 뒷면에 새 주소를 적어 주었어요.","같은 날 국민건강보험 절차도 할 수 있어요. 창구가 달라서 1층에서 2층으로 이동했어요.","전부 끝나기까지 한 시간쯤 걸렸지만, 일본어만으로 절차를 마칠 수 있어서 조금 자신감이 생겼어요.","모르는 것이 있으면 망설이지 말고 물어보는 게 좋아요. 담당자가 천천히 말해 줘요."],"vocab":["구청","절차","전입 신고","번호표","서류","생년월일","재류카드","국민건강보험","사양하다, 망설이다"],"grammar":[{"t":"～なければなりません","note":"의무를 나타내며 '반드시 해야 한다'는 뜻이에요. 「十四日以内に行かなければなりません」는 14일 이내에 꼭 가야 한다는 규정을 말해요."},{"t":"～ておく","note":"미리 준비해 둔다는 뜻이에요. 「書いておきました」는 기다리는 동안 미리 써 두어서 나중에 당황하지 않게 했다는 뜻이에요."},{"t":"～てくれる","note":"다른 사람이 나를 위해 무언가를 해 준다는 뜻이고, 고마운 마음이 담겨 있어요. 「書いてくれました」는 '(상대방이) 써 주었어요'라는 뜻이에요."}]},"a-n2-8":{"title":"지방 이주라는 선택","topic":"사회","trans":["최근 도시를 떠나 지방으로 이주하는 사람이 늘고 있다고 해요.","재택근무가 보급되면서 어디에 살아도 일할 수 있게 된 것이 큰 이유예요.","집세는 도시의 절반 이하이고 출퇴근 러시아워와도 상관없어서, 자연에 둘러싸인 생활이 매력적으로 보여요.","하지만 이주는 결코 쉬운 일이 아니에요.","차가 없으면 생활할 수 없는 지역도 많고, 의료나 교육 면에서 불편함을 느낄 때도 있어요.","지역 사람들과의 관계에 잘 녹아들 수 있을지도 큰 과제라고들 해요.","중요한 것은 이상만으로 결정하지 말고, 실제로 몇 번 직접 찾아가서 그 지역의 생활을 확인해 보는 일일 거예요."],"vocab":[{"w":"移住","m":"이주"},{"w":"普及","m":"보급"},{"w":"家賃","m":"집세"},{"w":"無縁","m":"인연이 없음, 상관없음"},{"w":"溶け込む","m":"녹아들다, 융화되다"},{"w":"課題","m":"과제, 해결해야 할 문제"},{"w":"足を運ぶ","m":"직접 찾아가다, 발걸음하다"},{"w":"確かめる","m":"확인하다"}],"grammar":[{"t":"~という(전문)","note":"「~라고 해요」: 増えているという。문장 끝의 という는 전해 들은 이야기나 인용을 나타내요."},{"t":"~によって","note":"「~로 인해, ~에 따라」: 普及によって~ようになった。원인이나 수단을 나타내요."},{"t":"決して~ない","note":"「결코 ~하지 않다」: 決して簡単なものではない。부정 표현과 함께 쓰는 부사예요."},{"t":"~かどうか","note":"「~인지 아닌지」: 溶け込めるかどうか。"},{"t":"~のではなく","note":"「~이/가 아니라 …」: 理想だけで決めるのではなく、実際に確かめる。"}]},"a-n1-7":{"title":"변해 가는 일본어","topic":"언어","trans":["'ら抜き言葉(ら 빼기 말)'라는 말을 들어 본 적이 있나요?","「食べられる」를 「食べれる」라고 말하는 식의 표현으로, 올바르지 않은 일본어라고 비판받는 일이 많아요.","하지만 언어학의 관점에서 보면 이것은 단순한 '흐트러짐'이 아니라 합리적인 변화라는 견해도 있어요.","「見られる」에는 수동·존경·가능이라는 여러 의미가 있지만, 「見れる」라고 하면 가능의 의미라는 것을 한눈에 알 수 있기 때문이에요.","애초에 말은 늘 변화해 왔어요.","지금 우리가 '올바르다'고 믿는 일본어도, 100년 전 사람들이 보면 흐트러진 말에 지나지 않아요.","변화를 한탄하기보다 왜 그렇게 변하는지를 생각하는 편이 말의 본질에 더 가까워질 수 있지 않을까요?"],"vocab":[{"w":"批判","m":"비판"},{"w":"乱れ","m":"흐트러짐, 혼란"},{"w":"合理的","m":"합리적"},{"w":"受身","m":"수동(태)"},{"w":"尊敬","m":"존경"},{"w":"嘆く","m":"한탄하다, 슬퍼하다"},{"w":"本質","m":"본질"},{"w":"近づく","m":"가까워지다, 다가가다"}],"grammar":[{"t":"~にほかならない","note":"「~에 지나지 않는다, 바로 ~이다」: 乱れた言葉にほかならない。단정하는 문어체 표현이에요."},{"t":"~ゆく","note":"「점점 ~해 가다(문어체)」: 変わりゆく日本語。ていく의 문어 형태로, 계속되는 변화를 나타내요."},{"t":"単なる~ではなく","note":"「단순한 ~이/가 아니라」: 単なる「乱れ」ではなく、合理的な変化。"},{"t":"~のではないだろうか","note":"「~이/가 아닐까(완곡한 주장)」: 近づけるのではないだろうか。반문하는 형태로 의견을 부드럽게 표현해요."}]},"a-n1-8":{"title":"외국인 인재와 일본 사회의 앞날","topic":"사회","trans":["일손 부족이 구조적인 문제가 된 지금, 외국인 인재를 받아들이는 일은 더 이상 임시방편이라고 할 수 없는 단계에 들어섰어요.","특정기능이나 고度인재 같은 제도가 갖춰지면서 체류자 수는 역대 최다를 계속 갈아치우고 있어요. 하지만 수가 늘었다고 해서 곧바로 정착을 뜻하는 것은 아니에요.","언어의 장벽, 집 구하기, 자녀 교육 등 생활의 기반이 갖춰지지 않으면 처우를 아무리 개선해도 사람은 뿌리를 내리지 못해요.","기업쯤 되면 채용한 뒤의 일본어 교육이나 지역 사회와의 연결 타누키를 만드는 일까지 맡아야 해요.","받아들이는 쪽의 의식도 함께 시험대에 올라 있어요. 상대를 '노동력'이 아니라 같은 지역에 사는 이웃으로 대할 수 있는지가 관건이에요.","제도가 어떻든 간에 마지막에 정착을 좌우하는 것은 아마도 일상적인 관계가 하나하나 쌓인 결과일 거예요.","외국인 인재를 둘러싼 논의는 사실 일본 사회가 어떤 공동체이고 싶은가라는 물음과 표리일체예요."],"vocab":["일손 부족","받아들임, 수용","임시방편","특정기능(비자 종류)","정착, 뿌리내림","처우","뿌리를 내리다","표리일체, 동전의 양면","시험대에 오르다, 질문을 받다"],"grammar":[{"t":"～ともなると","note":"어떤 수준이나 입장에 이르면 달라진다는 뜻이에요. 「企業ともなると」=기업쯤 되면 책임이 더 커진다는 뜻이에요."},{"t":"～いかんによらず","note":"앞의 내용이 어떻든 결과에는 영향이 없다는 뜻이에요. 「制度のいかんによらず」=제도가 어떻든 간에."},{"t":"～たところで","note":"해 봐야 소용없다는 뜻으로, 뒤에 부정적인 결과가 와요. 「改善したところで、根を下ろさない」=개선해 봐야 뿌리를 내리지 못한다."},{"t":"～わけではない","note":"부분 부정이에요. 「定着を意味するわけではない」=정착을 뜻하는 것은 아니라는 말이에요."}]},"a-n5-8":{"title":"은행에서 계좌를 만들다","topic":"생활","trans":["오늘은 은행에 계좌를 만들러 가요.","창구 직원이 「ざいりゅうカードと いんかんを おねがいします」라고 말했어요.","저는 가방에서 카드와 도장을 꺼냈어요.","용지에 이름과 주소, 전화번호를 써요. 한자가 어려워서 천천히 썼어요.","「캐시카드는 2주일쯤 지나면 집으로 도착해요」라고 알려 줬어요.","통장은 그날 바로 받을 수 있었어요. 일본에서 처음 만든 통장이에요.","조금 긴장했지만 일본어만으로 해낼 수 있어서 기뻤어요."],"vocab":["은행","계좌","도장","용지","전화번호","통장","도착하다","긴장하다"],"grammar":[{"t":"～に いきます(目的)","note":"동사 ます형에서 ます를 빼고 に いきます를 붙이면 '~하러 가요'라는 뜻이에요. 「こうざを つくりに いきます」=계좌를 만들러 가요."},{"t":"～と いいました","note":"다른 사람이 한 말을 인용할 때 쓰며, 문장 전체를 「と」 앞에 넣어요."},{"t":"～てくれる","note":"다른 사람이 나를 위해 무언가를 해 준다는 뜻으로, 고마운 느낌이 담겨 있어요. 「おしえて くれました」=(상대가) 알려 줬어요."}]},"a-n3-9":{"title":"일본에서 집 구하기","topic":"생활","trans":["일본에서 집을 빌리는 일은 생각보다 손이 많이 가요.","먼저 부동산 중개업소에 가서 월세 예산과 원하는 지역을 말해요. '역에서 도보 10분 이내'라는 조건을 붙이면 월세가 단번에 올라가요.","마음에 드는 집을 찾아도 바로 결정할 수는 없어요. 시키킹(보증금)·레이킹(사례금)·중개 수수료 등 처음에 목돈이 필요하기 때문이에요.","외국인은 보증인을 요구받는 경우가 많아요. 요즘은 보증 회사를 이용하는 편이 일반적이고, 월세의 절반 정도를 내고 계약해요.","심사를 통과할 수 있도록 근무처와 수입을 알 수 있는 서류를 미리 갖춰 두는 것이 좋아요.","집을 보러 갈 때는 채광이나 소음뿐 아니라 세탁기를 놓을 자리와 콘센트 개수도 함께 확인하면 좋아요. 사진으로는 알 수 없는 부분이야말로 직접 보는 의미가 있어요.","번거롭게 느껴지지만, 이 절차를 알고 있기만 해도 다음 이사는 훨씬 수월해질 거예요."],"vocab":["부동산 중개업소","월세","시키킹(보증금)","레이킹(사례금, 돌려받지 못함)","중개 수수료","보증인","심사","집 보러 가기(내견)","채광","손이 많이 가다"],"grammar":[{"t":"～ように(목적)","note":"바라는 상태를 이루기 위한 목적을 나타내요. 앞에는 주로 가능형이나 무의지 동사가 와요. 「審査に通るように」=심사를 통과할 수 있도록."},{"t":"～ほうがいい","note":"조언을 나타내요. 「そろえておいたほうがいい」=미리 갖춰 두는 것이 좋아요. 명령보다 부드럽지만 의사는 분명히 전달돼요."},{"t":"～こそ","note":"'바로 이것'이라고 강조해요. 「わからない部分こそ」=알 수 없는 부분이야말로."}]},"a-n2-9":{"title":"在留資格の更新という関門","topic":"사회","trans":["일본에서 사는 외국인에게 체류 자격 갱신은 피해 갈 수 없는 관문이에요.","기한 3개월 전부터 신청할 수 있지만, 서류 준비에 시간이 걸리므로 일찍 움직여서 나쁠 것은 없어요.","필요한 것은 신청서 외에 주민세 과세 증명서, 납세 증명서, 재직 증명서 등이에요. 막 이직한 사람은 고용 계약서를 요구받기도 해요.","심사에서는 수입이 안정적인지, 세금과 연금을 제대로 내고 있는지를 봐요.","즉, 평소에 절차를 미뤄 온 대가가 이 시기에 한꺼번에 돌아오는 셈이에요.","입국관리국 창구는 붐비기 때문에 온라인 신청을 이용하는 사람도 늘고 있어요. 그에 따라 절차의 흐름도 조금씩 바뀌고 있어요.","결과가 나올 때까지 몇 주 동안은 마음이 불안하지만, 필요한 서류를 갖추고 솔직하게 신고했다면 지나치게 걱정할 필요는 없어요."],"vocab":["체류 자격(비자)","갱신","관문, 난관","과세 증명서","납세 증명서","재직 증명서","입국관리국","신고","대가를 치르다, 청구서가 돌아오다"],"grammar":[{"t":"～に越したことはない","note":"'~하는 것보다 나은 것은 없다'는 뜻으로, 그렇게 하는 것이 가장 안전하다는 의미예요. 「早めに動くに越したことはない」=일찍 움직이는 것이 가장 좋아요."},{"t":"～というわけだ","note":"앞의 내용에서 결론을 이끌어 내요. 「回ってくるというわけだ」=즉, 결과가 그렇게 된다는 뜻이에요."},{"t":"～に伴って／それに伴い","note":"어떤 변화에 따라 다른 일도 함께 변해요. 「それに伴い、流れも変わりつつある」=그에 따라 절차도 바뀌고 있어요."},{"t":"～つつある","note":"변화가 계속 진행 중임을 나타내요. 「ている」보다 문어적이에요. 「変わりつつある」=점점 바뀌고 있어요."}]},"a-n4-9":{"title":"치과에 가요","topic":"생활","trans":["사흘 전부터 이가 아파서 근처 치과에 예약했어요.","접수처에서 보험증을 내자 문진표를 작성하라고 했어요. 언제부터 아픈지, 차가운 음식이 시린지 등을 적어요.","의사 선생님은 \"충치가 하나 있네요\"라고 말하면서 X선 사진을 보여 주셨어요.","오늘은 치아를 갈아 내고 약을 넣기만 했고, 다음 주에 한 번 더 오라고 하셨어요.","치료가 끝난 뒤에는 칫솔질하는 방법도 알려 주셨어요. 너무 세게 닦으면 잇몸이 상할 수 있대요.","일본 치과는 여러 번 다녀야 하지만, 그만큼 꼼꼼하게 치료해 줘요.","아프기 전에 반년에 한 번은 검진을 받으러 가는 게 좋겠다고 생각했어요."],"vocab":[{"w":"歯医者","m":"치과 의사, 치과"},{"w":"予約","m":"예약"},{"w":"保険証","m":"건강보험증"},{"w":"問診票","m":"문진표"},{"w":"しみる","m":"(차갑거나 뜨거운 것에) 시리다, 따끔거리다"},{"w":"虫歯","m":"충치"},{"w":"治療","m":"치료"},{"w":"歯ぐき","m":"잇몸"},{"w":"検診","m":"검진"}],"grammar":[{"t":"～ように言われる","note":"어떤 일을 하라는 요청이나 지시를 받았다는 뜻이에요(간접 지시). 「書くように言われました」는 '작성하라고 했어요'라는 뜻이에요."},{"t":"～そうです(전문)","note":"'~라고 해요, ~대요'라는 뜻이에요. 「傷めてしまうそうです」는 '상할 수 있대요'라는 뜻으로, 다른 사람에게 들은 정보예요."},{"t":"～なければなりません","note":"'~해야 해요'라는 의무를 나타내요. 「通わなければなりません」은 '여러 번 다녀야 해요'라는 뜻이에요."}]},"a-n3-10":{"title":"쓰레기 배출 규칙","topic":"생활","trans":["일본에서 살기 시작하고 가장 먼저 당황했던 건 쓰레기 분리배출 방법이었어요.","타는 쓰레기, 타지 않는 쓰레기, 재활용 쓰레기 등 구마다 분류도 수거일도 달라요. 이사하면 먼저 시청에서 받을 수 있는 안내표를 확인하는 게 좋아요.","페트병은 라벨과 뚜껑을 떼고 안을 가볍게 헹군 뒤에 내놓아요. 번거롭게 느껴지지만, 그 작은 수고에 따라 재활용할 수 있는지가 정해진다고 해요.","내놓는 시간에도 규정이 있어서, 대부분의 지역에서는 당일 아침 8시까지예요. 전날 밤에 내놓으면 까마귀가 어질러 놓을 수 있기 때문이에요.","대형 쓰레기는 미리 전화나 인터넷으로 신청하고, 편의점에서 스티커를 사서 붙여 둬요. 이걸 모르고 그냥 내놓았다가 주의를 받은 사람도 적지 않아요.","처음에는 너무 까다롭다고 느꼈지만, 살다 보니 익숙해졌어요.","쓰레기를 내놓는 방법은 그 지역에서 살기 위한 첫 번째 '공통 규칙'일지도 몰라요."],"vocab":[{"w":"戸惑う","m":"당황하다, 어찌할 바를 모르다"},{"w":"分類","m":"분류"},{"w":"資源ゴミ","m":"재활용 쓰레기"},{"w":"一覧表","m":"일람표, 안내표"},{"w":"すすぐ","m":"헹구다"},{"w":"ひと手間","m":"한 번의 수고, 작은 손질"},{"w":"荒らす","m":"어질러 놓다, 망가뜨리다"},{"w":"粗大ゴミ","m":"대형 쓰레기"},{"w":"申し込む","m":"신청하다"}],"grammar":[{"t":"～によって(~에 따라)","note":"앞에 오는 말에 따라 달라진다는 뜻이에요. 「区によって分類も違う」는 '구에 따라 분류도 달라요'라는 뜻이에요."},{"t":"～らしい(전문)","note":"들은 정보를 바탕으로 추측해서 말할 때 써요. 「決まるらしい」는 '정해진다고 해요'라는 뜻이에요."},{"t":"～ているうちに","note":"어떤 일을 계속하는 동안 어느새 변화가 생겼다는 뜻이에요. 「住んでいるうちに慣れてきた」는 '살다 보니 익숙해졌어요'라는 뜻이에요."}]},"a-n5-9":{"title":"공원에서 노는 하루","topic":"생활","trans":["토요일은 날씨가 좋았어요. 저는 친구와 공원에 가기로 약속했어요. 아침 아홉 시에 역에서 만났어요.","전날 밤에 도시락을 만들었어요. 달걀말이와 주먹밥, 채소를 넣었어요. 친구 몫도 조금 만들었어요.","공원까지 자전거를 타고 갔어요. 길에는 벚나무가 많이 있었어요. 바람이 기분 좋게 불었어요.","공원 벤치에서 도시락을 먹었어요. 정말 맛있었어요. 친구도 맛있다고 했어요.","먹은 뒤에는 친구와 배드민턴을 치기도 하고 사진을 찍기도 했어요. 모두 즐거워 보였어요.","저녁에 집에 돌아왔어요. 조금 피곤했지만 아주 즐거운 하루였어요. 다음 주에도 또 공원에 가고 싶어요."],"vocab":["토요일","날씨","친구","공원","약속","도시락","달걀말이","주먹밥","자전거","사진"],"grammar":[{"t":"へ(방향)","note":"이동하는 방향을 나타내요. 「行く」 같은 동사와 자주 함께 써요: 「こうえんへ 行く」."},{"t":"た形+あと","note":"동사의 た형에 「あと」를 붙이면 '~한 후에'라는 뜻이에요: 「たべた あと、あそびました」."},{"t":"~たり~たりする","note":"여러 동작이나 상태 중 몇 가지를 나열할 때 써요: 「バドミントンを したり、しゃしんを とったり しました」."},{"t":"も(~도)","note":"명사 뒤에 붙어 '~도 마찬가지로'라는 뜻을 나타내요: 「ともだちも おいしいと いいました」."}]},"a-n4-10":{"title":"무인 계산대","topic":"생활","trans":["지난주에 근처 슈퍼마켓에서 처음으로 무인 계산대를 써 봤어요. 점원이 없어도 직접 상품을 계산할 수 있어요.","먼저 바구니에서 상품을 하나씩 꺼내 바코드를 기계에 갖다 대요. 소리가 나면 계산이 제대로 됐다는 신호예요.","다음으로 화면을 보면서 현금으로 낼지 카드로 낼지 결제 방법을 선택해요. 현금이라면 돈 넣는 곳에 넣으면 돼요.","저는 처음이라서 어디를 눌러야 할지 몰라 조금 헤맸어요. 하지만 곤란할 때는 근처에 있던 점원이 바로 도와줬어요.","무인 계산대는 계산대 앞에 줄을 서지 않아도 돼서 시간이 없을 때 아주 편리해요. 다만 익숙하지 않은 사람에게는 조금 어려울지도 몰라요.","사용법에 익숙해지면 누구나 쉽게 쓸 수 있게 돼요. 앞으로 이용할 분은 먼저 천천히 화면을 보면서 해 보세요."],"vocab":["점원","상품","기계","화면","현금","지불하다","고르다, 선택하다","망설이다, 헤매다","돕다","익숙해지다"],"grammar":[{"t":"~てくれる","note":"다른 사람이 나를 위해 어떤 일을 해 줄 때 써요: 「店員さんが 手伝って くれました」(점원이 도와줬어요)."},{"t":"~なくてもいい","note":"어떤 일을 하지 않아도 된다는 뜻이에요: 「レジに ならばなくても いいです」(줄을 서지 않아도 돼요)."},{"t":"~ずつ","note":"'~씩'이라는 뜻으로, 똑같은 양으로 나누는 것을 나타내요: 「一つずつ とりだす」(하나씩 꺼내요)."},{"t":"~か~か","note":"둘 중에서 하나를 고를 때 써요: 「げんきんか カードか」(현금이냐 카드냐)."}]},"a-n2-10":{"title":"보고·연락·상담의 실천","topic":"직장","trans":["일본 직장에서 흔히 말하는 「報・連・相」은 외우기는 쉽지만, 실제로 실천하려면 어려워요.","특히 외국인 직원이 가장 헷갈려 하는 부분은 「결론이 아직 나오지 않은 단계에서 보고해도 될까」 하는 판단이에요.","결론부터 말하면, 나오지 않았어도 괜찮아요. 오히려 진행이 순조롭지 않을 때일수록 빨리 공유하기를 기대해요.","상사가 알고 싶은 것은 완벽한 보고가 아니라, 리스크가 손쓸 수 없게 되기 전에 건네는 한마디이기 때문이에요.","「〇〇の件、今のところ半分ほど進んでいますが、資料待ちで少し遅れそうです」——이 정도면 충분히 제 역할을 해요.","상담도 마찬가지로, 답을 갖고 가지 않아도 상관없어요. 「어디에서 고민하고 있는지」를 말로 표현할 수 있다면, 그것만으로도 상담이 돼요.","보고·연락·상담을 상하 관계의 예절이라기보다 팀이 사고를 막기 위한 장치라고 생각하면, 부담이 훨씬 가벼워질 거예요."],"vocab":[{"w":"実践","m":"실천"},{"w":"とりわけ","m":"특히"},{"w":"つまずく","m":"발이 걸려 넘어지다, 좌절하다"},{"w":"進捗","m":"진척, 진행 상황"},{"w":"思わしくない","m":"신통치 않다, 좋지 않다"},{"w":"手遅れ","m":"때늦음, 늦어서 손쓸 수 없음"},{"w":"言語化","m":"말로 표현함"},{"w":"作法","m":"예절, 규범"},{"w":"仕組み","m":"구조, 체계"}],"grammar":[{"t":"～となると","note":"막상 그 상황이 되면 달라진다는 뜻이에요. 「実践となると難しい」=막상 실천하려면 어렵다."},{"t":"～こそ","note":"바로 그때·그것임을 강조해요. 「思わしくないときこそ」=순조롭지 않을 때일수록(더욱)."},{"t":"～ても構わない","note":"~해도 상관없다. 「行っても構わない」=가도 상관없다."},{"t":"～というより","note":"A라기보다 B. 「作法というより仕組み」=예절이라기보다 장치."}]},"a-n1-9":{"title":"주거 공간에 깃든 거리감","topic":"문화","trans":["일본의 주거 공간 곳곳에는 말로 드러내지 않는 거리 두기 방식이 스며 있어요.","현관에서 신발을 벗는 습관 하나만 봐도, 거기에는 「바깥」과 「안」을 가르는 분명한 선이 그어져 있어요. 현관 단차를 넘는 동작은 단순한 이동이 아니라, 말하자면 전환의 의식이에요.","후스마나 쇼지 같은 칸막이는 완전히 닫아 버리지 않는다는 점에서 시사하는 바가 커요. 소리도 기척도 통과시키는 얇은 한 장이, 그래도 공간을 나눈 셈 치는 것——이 모호함이야말로 좁은 집에서 다른 사람과 함께 살아가는 지혜였을 거예요.","공동주택이 주류가 된 지금도 그런 감각은 모습을 바꿔 남아 있어요. 생활 소음에 대한 신경질적일 만큼의 배려는 벽이 얇아서라기보다, 서로의 영역을 침범하지 않는다는 예절의 연장선상에 있어요.","다만 이런 거리감은 밖에서 온 사람은 읽어 내기 어려워요. 인사를 해야 할지 말아야 할지, 어디까지 다가가도 되는지——명문화되어 있지 않은 만큼 망설일 때도 많아요.","하지만 뒤집어 보면, 그것은 저마다 적당한 선을 스스로 가늠하도록 맡겨져 있다는 뜻이기도 해요.","주거 공간이란, 다른 사람과의 거리를 어떻게 잴 것인가라는 물음이 매일 조용히 되풀이되는 곳일지도 몰라요."],"vocab":[{"w":"随所","m":"곳곳, 도처"},{"w":"隔てる","m":"사이를 가르다, 떼어 놓다"},{"w":"上がり框","m":"현관의 단차(마루 가장자리)"},{"w":"儀式","m":"의식"},{"w":"仕切り","m":"칸막이"},{"w":"示唆に富む","m":"시사하는 바가 크다, 시사점이 많다"},{"w":"気配","m":"기척, 낌새"},{"w":"配慮","m":"배려"},{"w":"侵す","m":"침범하다"},{"w":"委ねる","m":"맡기다, 일임하다"}],"grammar":[{"t":"～をとっても","note":"하나를 예로 들어 봐도. 「習慣ひとつをとっても」=습관 하나만 봐도."},{"t":"～ゆえに／～ゆえ","note":"문어체 원인 표현. 「壁の薄さゆえ」=벽이 얇기 때문에."},{"t":"～というより","note":"A라기보다 B. 표현을 바로잡으며 뒤의 내용에 무게를 두어요."},{"t":"裏を返せば","note":"뒤집어 말하면. 같은 일을 반대편에서 해석할 때 써요."}]},"a-n3-11":{"title":"報連相の大切さ","topic":"직장","trans":["일본 회사에서는 「報連相」이 아주 중요하다고들 해요. 이것은 보고, 연락, 상담 세 가지를 합친 말이에요.","업무가 어느 정도 진행되고 있는지를 상사에게 전하는 것을 보고라고 해요. 문제가 생기면 곧바로 보고해야 해요.","연락은 필요한 정보를 관련된 사람에게 전하는 거예요. 일정이 바뀌었을 때처럼 빠른 연락이 중요하게 여겨져요.","상담은 혼자 결정할 수 없는 일을 상사나 동료에게 묻는 거예요. 사소한 일이라도 상담하면 큰 실수를 막을 수 있어요.","외국인 직원에게 이런 報連相 습관은 처음에는 어렵게 느껴질 수도 있어요. 자기 나라에서는 스스로 판단해서 일을 진행하는 것이 좋은 평가를 받는 경우도 있기 때문이에요.","하지만 報連相을 제대로 하면 팀 안에서 신뢰를 얻기 쉬워져요. 일본 회사에서 일할 거라면 이런 사고방식을 이해해 두는 것이 도움이 될 거예요."],"vocab":[{"w":"報連相","m":"보고·연락·상담을 합쳐 부르는 말"},{"w":"報告","m":"보고"},{"w":"連絡","m":"연락"},{"w":"相談","m":"상담, 의논"},{"w":"進み具合","m":"진행 상황, 진척도"},{"w":"上司","m":"상사"},{"w":"同僚","m":"동료"},{"w":"信頼","m":"신뢰"},{"w":"判断","m":"판단"},{"w":"評価","m":"평가"}],"grammar":[{"t":"~と言われています","note":"'~라고들 해요, ~라고 알려져 있어요'라는 뜻이에요. 예: 「報連相が大切だと言われています」(報連相이 중요하다고들 해요)."},{"t":"~ことです","note":"동사구를 명사처럼 만들어 '~하는 것이에요'라는 뜻을 나타내요. 예: 「情報を伝えることです」(정보를 전하는 것이에요)."},{"t":"~ば","note":"'~하면'이라는 조건을 나타내요. 예: 「相談すれば、失敗を防げます」(상담하면 실수를 막을 수 있어요)."},{"t":"~かもしれません","note":"'~일지도 몰라요'라는 추측을 나타내요. 예: 「難しく感じられるかもしれません」(어렵게 느껴질지도 몰라요)."}]},"a-n5-10":{"title":"レストランで ちゅうもんします","topic":"생활","trans":["오늘 저녁에 친구와 레스토랑에 갔어요.","메뉴를 보고 요리를 골랐어요.","점원을 불렀어요. 정식과 차를 주문했어요.","요리가 빨리 나왔어요. 아주 맛있었어요.","다 먹은 뒤에 계산대에서 돈을 냈어요. 카드도 쓸 수 있어서 편했어요."],"vocab":[{"w":"レストラン","m":"레스토랑, 식당"},{"w":"メニュー","m":"메뉴"},{"w":"てんいんさん","m":"점원"},{"w":"よびます","m":"부르다"},{"w":"ていしょく","m":"정식"},{"w":"ちゅうもんします","m":"주문하다"},{"w":"りょうり","m":"요리"},{"w":"レジ","m":"계산대"},{"w":"はらいます","m":"지불하다, 내다"},{"w":"べんり","m":"편리함, 편함"}],"grammar":[{"t":"〜て、〜(て形接續)","note":"동사의 て형으로 두 가지 동작을 이어요. 예: 「メニュー を みて、りょうり を えらびました。」"},{"t":"〜ました(過去式)","note":"과거에 있었던 동작을 나타내요. 예: 「てんいん さん を よびました。」"},{"t":"〜あと、〜","note":"어떤 동작을 한 뒤를 나타내요. 예: 「たべた あと、レジ で おかね を はらいました。」"},{"t":"〜も","note":"'~도'라는 뜻이에요. 예: 「カード も つかえて、べんり でした。」"}]},"a-n4-11":{"title":"전철에 우산을 두고 내린 날","topic":"생활","trans":["오늘 전철 안에 우산을 두고 내렸어요. 정신을 차리고 보니 전철은 벌써 다음 역에 도착해 있었어요. 너무 난감해서 역의 분실물 센터에 가기로 했어요.","직원에게 우산을 잃어버렸다고 설명했어요. 「특징을 알려 주세요」라고 해서 색과 모양을 말씀드렸어요. 「검은색이고 손잡이가 조금 휜 우산이에요」라고 말했어요. 직원은 「잠시만 기다려 주세요, 찾아볼게요」라고 말해 주었어요.","잠시 기다리니 비슷한 우산을 찾은 것 같다고 했어요. 안쪽에서 우산을 가져와 주었는데, 그것은 분명 제 우산이었어요. 바로 받을 수 있어서 정말 안심이 되었어요. 앞으로는 전철에서 내릴 때 두고 내린 물건이 없는지 확인하려고 해요."],"vocab":["분실물, 두고 내린 물건","알아차리다, 깨닫다","난처하다, 곤란하다","특징","휘다, 굽다","발견되다, 찾아지다","받다, 수령하다","안심하다, 한시름 놓다","확인하다"],"grammar":[{"t":"〜たら","note":"앞의 동작이 일어난 뒤 이어서 뒤의 결과나 발견이 나타남을 나타내요. 의외라는 뉘앙스가 있는 경우가 많아요. 예문: 「気がついたら、もう電車は次の駅に着いていました。」"},{"t":"가능형","note":"어떤 일을 할 수 있는 능력이나 상태를 나타내요. 예문: 「すぐに受け取れて、本当にほっとしました。」"},{"t":"수수 표현(〜てくれる/〜てもらう)","note":"다른 사람이 나를 위해 어떤 행동을 해 주거나, 상대에게 부탁해서 도움을 받는 것을 나타내요. 예문: 「係の人は…と言ってくれました。」、「奥から傘を持ってきてもらったら」"},{"t":"〜そうだ(양태)","note":"겉모습이나 상황으로 보아 곧 일어날 것 같다고 판단할 때 써요. 예문: 「同じような傘が見つかりそうだと言われました。」"}]},"a-n3-12":{"title":"비즈니스 메일의 기본","topic":"직장","trans":["일본 회사에서 일할 때 메일을 쓰는 데에는 몇 가지 기본 규칙이 있어요. 메일은 전화와 달리 상대가 편한 시간에 읽을 수 있다는 장점이 있어요. 잘못 쓰면 실례가 되는 인상을 줄 수도 있기 때문에 신입 사원은 선배에게 많이 배워요.","먼저 제목은 한눈에 내용을 알 수 있도록 간결하게 쓰는 것이 중요해요. 「会議の件」만 쓰지 말고 「来週の会議の日程について」처럼 구체적으로 쓰는 것이 좋아요. 제목이 알아보기 어려우면 상대가 바쁠 때 메일을 놓칠 수도 있어요. 다만 제목을 길게만 쓰면 된다는 뜻은 아니고, 짧게 정리하는 요령도 필요해요.","메일의 첫머리에는 「お世話になっております」라는 말을 자주 써요. 이는 상대와의 관계에 감사를 표하는 인사로, 회사 밖 사람에게도 회사 안 사람에게도 쓰는 표현이에요. 처음 연락하는 상대에게는 「はじめてご連絡いたします」 같은 표현을 쓰기도 해요. 본문에서는 용건을 알기 쉽게 전달하기 위해 짧은 문장으로 정중하게 쓰는 것이 요구돼요.","메일의 마지막은 「よろしくお願いいたします」라는 말로 맺기로 한 사람이 많아요. 이 말이 있으면 글 전체가 정중한 인상이 되고, 상대도 기분 좋게 읽을 수 있어요. 또 메일을 받으면 가능한 한 빨리 답장하는 것도 중요한 매너 중 하나예요. 바로 답을 줄 수 없는 경우에도 「確認して後日ご連絡します」라고 한마디 보내 두면 상대가 안심해요."],"vocab":["메일 제목","간결하다","구체적","놓치다, 못 보고 지나치다","정중함, 공손함","답장","매너, 예절","안심","신입 사원","장점"],"grammar":[{"t":"〜ように","note":"어떤 목적이나 상태를 이루기 위해 무언가를 한다는 뜻을 나타내요. 본문의 「件名は一目で内容がわかるように、簡潔に書くことが大切です」."},{"t":"〜わけではない","note":"전부 그렇다는 것은 아니라고 완곡하게 부분 부정할 때 써요. 본문의 「件名を長くしすぎればよいというわけではなく」."},{"t":"〜ことにする","note":"스스로 정한 방침이나 습관을 나타내요. 본문의 「よろしくお願いいたします、という言葉で締めることにしている人が多いです」."},{"t":"〜ておく","note":"나중을 위해 미리 어떤 일을 해 두는 것을 나타내요. 본문의 「確認して後日ご連絡します、と一言送っておくと安心されます」."}]},"a-n5-11":{"title":"첫 IC카드","topic":"생활","trans":["일본에 온 뒤 처음으로 역에서 IC카드를 샀어요. 기계에 1,000엔을 넣었어요.","전철을 탈 때는 개찰구에서 카드를 대요. 「삐」 하고 짧은 소리가 나요.","표를 사는 시간이 필요 없어서 정말 편해요.","게다가 전철뿐만 아니라 버스나 편의점에서도 쓸 수 있어요.","어제 개찰구에서 「딩동」 하고 큰 소리가 났어요. 카드에 든 돈이 부족했거든요.","역무원이 「저쪽 기계에서 충전하세요」 하고 알려 줬어요.","지금은 역에 들어가기 전에 카드 잔액을 확인해요."],"vocab":[{"w":"駅","m":"역"},{"w":"機械","m":"기계"},{"w":"改札","m":"개찰구"},{"w":"切符","m":"표, 승차권"},{"w":"便利","m":"편리함, 편하다"},{"w":"足りる","m":"충분하다, 모자라지 않다"},{"w":"駅員","m":"역무원"},{"w":"教える","m":"알려 주다, 가르치다"},{"w":"チャージする","m":"충전하다"}],"grammar":[{"t":"～とき","note":"'~할 때'를 나타내요. 동사 사전형+とき: 「でんしゃ に のる とき」=전철을 탈 때."},{"t":"～ことができる","note":"능력이나 가능성을 나타내요. 동사 사전형+ことができる: 「つかう こと が できます」=쓸 수 있어요."},{"t":"～まえに","note":"'~하기 전에'를 나타내요. 동사는 항상 사전형을 써요: 「えき に 入る まえ に」=역에 들어가기 전에."}]},"a-n4-12":{"title":"독감 예방접종","topic":"건강","trans":["10월이 되자 근처 병원에 「독감 예방접종 시작했습니다」라는 안내문이 붙어 있었어요.","작년 겨울에 저는 독감에 걸려서 일주일이나 회사를 쉬어야 했어요.","그래서 올해는 일찍 예방접종을 받기로 했어요.","전화로 예약하고 갔더니 접수처에서 문진표를 줬어요. 체온을 재고 몸 상태에 대해 적어요.","주사는 생각보다 아프지 않았어요. 끝난 뒤에는 대기실에서 잠시 쉬라고 했어요.","예방접종에는 건강보험을 쓸 수 없어서 조금 비싸다고 느꼈어요. 가격은 병원마다 다르다고 하는데, 저는 3,500엔이었어요.","효과가 나타나기까지 2주 정도 걸린다고 해요. 유행하기 전에 맞아 두면 안심하고 겨울을 보낼 수 있어요."],"vocab":[{"w":"予防接種","m":"예방접종"},{"w":"受付","m":"접수처"},{"w":"早め","m":"좀 이르게, 일찌감치"},{"w":"渡す","m":"건네주다"},{"w":"調子","m":"상태, 컨디션"},{"w":"注射","m":"주사"},{"w":"待合室","m":"대기실"},{"w":"健康保険","m":"건강보험"},{"w":"効果","m":"효과"},{"w":"流行する","m":"유행하다"}],"grammar":[{"t":"～なければなりません","note":"'~해야 해요', 어쩔 수 없이 해야 한다는 뜻이에요. 「休まなければなりませんでした」=(그때) 쉬어야 했어요."},{"t":"～ことにする","note":"스스로 결정했을 때 써요. 「受けることにしました」=받기로 했어요."},{"t":"～そうです(전문)","note":"'~라고 해요'. 「違うそうですが」「かかるそうです」=다른 사람에게 들은 내용이고, 직접 확인한 것은 아니에요."},{"t":"～ておく","note":"미리 준비해 두는 것을 나타내요. 「受けておく」=(유행하기 전에) 맞아 두다."}]},"a-n4-13":{"title":"시치고산 날","topic":"문화","trans":["11월의 어느 토요일, 저는 친구와 근처 신사로 산책하러 갔어요. 신사 경내에는 예쁜 기모노를 입은 아이들과 가족이 많이 있었어요. 어린 여자아이가 빨간 기모노를 입고 기쁜 듯이 사진을 찍고 있었어요.","일본인 친구 다나카 씨가 이건 시치고산이라고 알려 줬어요. 시치고산은 세 살, 다섯 살, 일곱 살이 된 아이의 성장을 축하하는 행사예요. 가족은 신사에서 기도를 받으며 아이가 건강하게 자라기를 빌어요.","다나카 씨는 아이들이 들고 있는 긴 종이봉투를 가리켰어요. 안에는 지토세아메라는 가늘고 긴 엿이 들어 있어요. 아이가 오래 살기를 바라는 가족의 소원이 담겨 있다고 해요. 지토세아메는 화과자 가게 등에서도 살 수 있다고 다나카 씨가 말했어요. 만약 나중에 아이가 생기면 저도 지토세아메를 준비해서 축하해 주고 싶어요."],"vocab":["신사","신사 경내","기모노(일본 전통 옷)","성장","축하하다","행사, 의식, 풍습","자라다","지토세아메(장수를 기원하는 가늘고 긴 엿)","장수","소원, 바람"],"grammar":[{"t":"〜てくれる/〜てもらう","note":"다른 사람이 나를 위해 무언가를 해 주는 것을 나타내요. 「田中さんが…教えてくれました」는 상대가 먼저 나서서 도와준 경우이고, 「お祈りをしてもらって」는 상대에게 부탁해서 도움을 받는 경우예요."},{"t":"〜そうだ(양태・전문)","note":"い형용사나 동사의 어간에 붙으면 '~해 보인다'는 뜻이에요: 「うれしそうに写真をとっていました」. 보통형에 붙으면 '~라고 한다'는 전문의 뜻이에요: 「願いがこめられているそうです」."},{"t":"〜たら","note":"가정이나 조건을 나타내며 '~하면'이라는 뜻이에요: 「もし将来子どもができたら、わたしも…お祝いしたいです」."},{"t":"가능형","note":"'~할 수 있다'는 뜻이에요. 「買える」는 「買う」의 가능형이에요: 「和菓子屋さんなどでも買える」."}]},"a-n5-13":{"title":"겨울 쇼핑","topic":"생활","trans":["요즘 많이 추워졌어요. 토요일에 친구와 함께 가게에 갔어요.","저는 검은색 코트를 갖고 싶었어요. 친구가 \"빨간 것도 괜찮아\"라고 말했어요. 저는 점원에게 \"입어 봐도 돼요?\"라고 물었어요.","빨간 코트는 정말 예뻤어요. 코트와 장갑과 머플러를 샀어요. 전부 제가 좋아하는 색이에요."],"vocab":["토요일","친구","가게, 상점","코트","장갑","머플러, 목도리","검은색의, 검은","빨간색의, 빨간","색, 색깔","물었어요(聞く의 과거형)"],"grammar":[{"t":"〜く なりました","note":"い형용사에서 「い」를 빼고 「く」를 붙인 뒤 「なりました」를 이어서 상태의 변화를 나타내요. 예: 「さいきん とても さむく なりました。」"},{"t":"〜が ほしい です","note":"어떤 것을 갖고 싶다는 뜻이에요. 과거의 '갖고 싶었다'는 「ほしかった です」를 써요. 예: 「わたし は 黒い コート が ほしかった です。」"},{"t":"〜ても いい ですか","note":"'~해도 돼요?'라고 허락을 구할 때 써요. 예를 들어 옷을 입어 봐도 되는지 점원에게 물을 때 쓰죠. 예: 「きても いい ですか」."},{"t":"A と B と C を 買いました","note":"「と」로 명사를 이어서 'A와 B와 C'라는 뜻을 나타내요. 예: 「コート と てぶくろ と マフラー を 買いました。」"}]},"a-n3-14":{"title":"단풍놀이를 떠나요","topic":"문화","trans":["10월 말에 동료인 다나카 씨가 「今週末、紅葉を見に行きませんか」라고 권했어요. 일본에서는 가을에 산이나 공원에서 물든 잎을 즐기는 것을 「紅葉狩り」라고 부르는데, 예로부터 많은 사람들에게 사랑받아 왔어요. 저는 단풍을 좋아하지만, 유명한 곳은 사람이 많다고 들어서 조금 걱정이 됐어요.","다나카 씨는 「人込みを避けるために、朝早く出発するのはどうでしょうか」라고 제안해 줬어요. 낮이 되면 주차장도 도로도 붐비니까 오전 중에 도착하도록 하면 여유롭게 걸을 수 있다고 해요. 평일이 한산한 경우가 많지만 항상 조용한 것은 아니니까 너무 기대하지 않는 편이 좋아요.","다음으로 관광 협회나 날씨 사이트에 공개된 「紅葉情報」를 찾아보기로 했어요. 거기에는 「色づき始め」, 「見ごろ」 같은 말로 나무의 상태가 알기 쉽게 적혀 있어요. 단풍이 절정인 시기는 장소에 따라 달라지니까 출발하기 전에 확인하라고 다나카 씨가 알려 줬어요. 의논한 끝에 산과 가까운 작은 공원을 고르고, 아침 첫 전철을 타고 가기로 했어요.","당일에는 조금 졸렸지만 일찍 일어난 보람이 있게 길에는 사람이 거의 없었어요. 붉은색과 노란색 잎이 아침 햇살을 받아 마치 공기까지 물든 것처럼 보였어요. 바쁜 하루하루 속에서 계절이 바뀌는 것을 천천히 느낄 기회는 많지 않아요. 돌아오는 길에 「誘ってくださって、ありがとうございました」라고 인사했어요. 다나카 씨가 「来年も行きましょう」라고 웃으며 말해서, 저는 벌써부터 다음 가을이 기대돼요."],"vocab":["단풍놀이","동료","인파, 붐비는 사람들","피하다","제안","단풍 정보","절정기, 보기 좋은 시기","물들다","비추다","기회"],"grammar":[{"t":"〜ように(요청・목적)","note":"어떤 상태가 되도록 무언가를 하거나, 상대에게 무언가를 하라고 말할 때 써요. 예: 「確認するように田中さんが教えてくれた」「午前のうちに着くようにすれば」."},{"t":"〜わけではない","note":"'~라는 것은 아니다'라는 뜻으로, 부분 부정을 나타내요. 예: 「いつも静かなわけではないので」."},{"t":"〜ことにする","note":"말하는 사람이 스스로 무언가를 하기로 결정했을 때 써요. 예: 「紅葉情報を調べることにした」「朝一番の電車で行くことにした」."},{"t":"敬語(くださる)","note":"「〜てくださる」는 「〜てくれる」의 존경 표현으로, 상대의 호의에 감사할 때 써요. 예: 「誘ってくださって、ありがとうございました」."}]},"a-n5-12":{"title":"편의점 오뎅","topic":"생활","trans":["겨울 저녁, 편의점에 들어갔어요. 계산대 옆에 오뎅이 있었어요. 좋은 냄새가 나서 배가 고파졌어요.","저는 「だいこん と たまご を ください」라고 말했어요. 점원이 「つゆ と からし は いりますか」라고 물었어요. 저는 「つゆ だけ ください」라고 말했어요.","집에 돌아가서 바로 먹었어요. 뜨끈한 오뎅 덕분에 몸이 따뜻해졌어요."],"vocab":["오뎅","무","달걀","계산대","국물","겨자(매운 양념)","점원","냄새","따뜻하다","들어가다"],"grammar":[{"t":"〜を ください","note":"상대에게 물건을 달라고 하거나 주문할 때 써요. 예: 「だいこん と たまご を ください」. 한 가지만 원할 때는 「だけ」를 쓸 수 있어요. 예: 「つゆ だけ ください」."},{"t":"〜と 言いました/聞きました","note":"「と」는 말하거나 물은 내용을 인용해요. 예: 「てんいん さん が『つゆ と からし は いりますか』と 聞きました」."},{"t":"동사 て형、〜","note":"「て」로 앞뒤 동작이나 이유를 이어요. 예: 「いい におい が して、おなか が すきました」「うち に かえって、すぐ 食べました」."},{"t":"い형용사 く なります","note":"상태의 변화를 나타내요. 예: 「からだ が あたたかく なりました」(몸이 따뜻해졌어요)."}]},"a-n3-13":{"title":"부재중 방문 안내표가 들어 있을 때","topic":"생활","trans":["퇴근해서 집에 오니 우편함에 종이 한 장이 들어 있었어요. 택배 「부재중 방문 안내표」였어요.","집을 비운 사이에 택배가 와서, 다시 배달해 달라고 요청해야 해요. 이것을 「재배달」이라고 해요.","예전에는 종이에 적힌 번호로 전화하는 게 보통이었지만, 지금은 스마트폰으로 간편하게 신청할 수 있어요. 종이에 있는 QR코드를 스캔해서 원하는 날짜와 시간대를 고르기만 하면 끝이에요.","다만 안내표에는 보관 기한도 적혀 있어요. 서둘러 신청하지 않으면 택배가 보낸 사람에게 반송될 수도 있으니 주의해야 해요.","한편 재배달에는 트럭 연료도 인력도 들어요. 택배 기사 부족이 사회 문제가 된 지금은 가능하면 한 번에 받는 것이 요구되고 있어요.","그래서 편리한 것이 「문 앞 배송(置き配)」과 택배함이에요. 현관 앞이나 택배함에 물건을 놓아 두게 하면 집에 없어도 받을 수 있어요.","저도 요즘은 온라인 쇼핑으로 주문할 때 수령 방법까지 생각해 두려고 해요. 작은 노력이지만, 나에게도 택배 기사님에게도 좋은 습관이에요."],"vocab":[{"w":"郵便受け","m":"우편함"},{"w":"宅配便","m":"택배"},{"w":"不在連絡票","m":"부재중 방문 안내표"},{"w":"留守","m":"집을 비움, 부재중"},{"w":"再配達","m":"재배달"},{"w":"時間帯","m":"시간대"},{"w":"保管期限","m":"보관 기한"},{"w":"送り主","m":"보낸 사람"},{"w":"人手","m":"일손, 인력"},{"w":"置き配","m":"문 앞 배송"},{"w":"通販","m":"온라인 쇼핑, 통신 판매"}],"grammar":[{"t":"～ように頼む","note":"다른 사람에게 어떤 일을 해 달라고 부탁할 때 써요(간접 인용). 「届けてくれるように頼まなければならない」=다시 배달해 달라고 부탁해야 해요."},{"t":"～だけで済む","note":"~하기만 하면 해결되고 더 필요한 게 없다는 뜻이에요. 「選ぶだけで済む」=고르기만 하면 끝나요."},{"t":"～ないと","note":"「~하지 않으면 (…하게 돼요)」라는 뜻으로, 뒤에는 주로 좋지 않은 결과가 와요. 「早めに手続きしないと、…返されてしまう」."},{"t":"～ようにしている","note":"의식적으로 들인 습관을 나타내요. 「考えるようにしている」=생각해 두려고 해요."}]},"a-n2-11":{"title":"이자카야의 「お通し」","topic":"문화","trans":["일본의 이자카야에서 자리에 앉으면 주문하지 않았는데도 작은 그릇의 안주가 나올 때가 있어요. 이것이 바로 「お通し」예요.","간사이 지방에서는 「突き出し」라고 부르는 경우도 많고, 에다마메나 조림, 무침 등 내용은 가게마다 다양해요.","일본에 처음 온 사람 중에는 계산할 때 오토시 값이 더해진 것을 보고 부당한 청구가 아닌지 당황하는 사람도 적지 않아요.","시세는 대략 300엔에서 500엔 정도라고 하며, 가게 입장에서는 자릿세에 가까운 의미를 가져요.","또 요리가 나올 때까지 손님이 심심하지 않도록 하려는 배려라는 시각도 있어요.","그렇다고는 해도 거절할 수 있는지는 가게 방침에 달려 있고, 요즘은 お通し를 내지 않는 가게도 늘고 있어요. 신경 쓰인다면 가게에 들어갈 때 한마디 물어보면 되는 일이에요.","배경을 알고 있다면 낯선 작은 안주도 일본 술 문화의 일부로 즐길 수 있지 않을까요?"],"vocab":[{"w":"居酒屋","m":"이자카야(일본식 술집)"},{"w":"小鉢","m":"작은 그릇, 작은 사발"},{"w":"お通し","m":"(이자카야의) 기본 안주"},{"w":"会計","m":"계산"},{"w":"加算","m":"가산, 더함"},{"w":"戸惑う","m":"당황하다, 어쩔 줄 모르다"},{"w":"相場","m":"시세"},{"w":"意味合い","m":"의미, 뉘앙스"},{"w":"手持ち無沙汰","m":"할 일이 없어 심심함"},{"w":"心遣い","m":"배려, 마음 씀씀이"},{"w":"方針","m":"방침"}],"grammar":[{"t":"～際(に)","note":"「~할 때」라는 뜻으로 「とき」보다 격식 있는 표현이에요. 「会計の際に」=계산할 때."},{"t":"～次第","note":"「~에 달려 있다, ~에 따라 정해진다」라는 뜻이에요. 「店の方針次第であり」=가게 방침에 달려 있고."},{"t":"～つつある","note":"어떤 변화가 계속 진행 중임을 나타내요. 「増えつつある」=점점 늘고 있어요."},{"t":"とはいえ","note":"「그렇다고는 해도」라는 뜻으로, 앞의 내용을 인정하면서 유보나 반대되는 관점을 덧붙일 때 써요."}]},"a-n3-15":{"title":"첫 연말정산","topic":"직장","trans":["연말이 가까워질 무렵, 인사부에서 「年末調整のご案内」라는 메일과 서류가 왔어요. 서류에는 가족 부양 상황과 보험료를 쓰는 칸이 있었는데, 무엇부터 써야 할지 몰랐어요. 일본에서 일하는 건 처음이라 「年末調整」라는 말 자체를 들어 본 적도 없었어요.","옆자리의 다나카 씨에게 물어보니 \"매년 하는 절차니까 걱정하지 않아도 돼요\"라고 말해 주었어요. 매달 월급에서 빠져나가는 세금은 임시로 계산한 것이고, 연말에 1년 치를 다시 계산한다고 해요. 가족 상황이나 낸 보험료에 따라 세금이 달라지기 때문에 정확하게 쓰는 게 중요하대요. 다만 작성 방법은 회사마다 조금씩 달라서, 모르는 부분은 인사팀에 직접 물어보라는 말을 들었어요.","다음 날 인사팀의 사토 씨에게 질문하러 갔더니, 작성 예시를 보여 주면서 하나하나 친절하게 설명해 주었어요. 직접 낸 보험이 있으면 보험 회사에서 받은 증명서가 필요할 수도 있다고 해요. 질문하는 게 싫은 건 아니었지만, 바빠 보이는 인사팀에 말을 걸기가 어렵다고 생각했어요. 그런데 사토 씨는 \"처음이면 물어보는 게 당연해요\"라며 웃으면서 대답해 주었어요.","집에 돌아와서는 집에 있는 보험 서류를 찾아 쓸 내용을 천천히 확인하기로 했어요. 자세한 절차와 제출 방법은 회사마다 다르니, 꼭 회사의 설명을 확인하세요. 연말정산은 번거로워 보이지만, 1년 치 세금을 정확하게 맞추는 중요한 절차라는 걸 알게 되었어요."],"vocab":["연말정산(연말에 소득세를 다시 정산하는 일본의 제도)","인사부","부양","보험료","절차","작성 예시","증명서","확인","정중함, 꼼꼼함","월급"],"grammar":[{"t":"〜ように言われた","note":"어떤 일을 하라고 당부받거나 요구받았음을 나타내요(간접 인용). 예: 「わからない点は人事に直接聞くように言われた」"},{"t":"〜わけではない","note":"'~라는 것은 아니다'라는 뜻으로, 부분 부정을 나타내며 있을 수 있는 오해를 지워요. 예: 「質問するのが嫌なわけではなかったが」"},{"t":"〜ことにする","note":"말하는 사람이 스스로 어떤 일을 하기로 결정했음을 나타내요. 예: 「ゆっくり確認することにした」"},{"t":"〜そうだ(전문)","note":"보통형에 붙어서 남에게 들은 소식을 전해요. 예: 「年末に一年分を計算し直すのだそうだ」"}]},"a-n4-14":{"title":"겨울 전기요금","topic":"생활","trans":["일본의 겨울은 집 안에서도 생각보다 훨씬 추워요. 오래된 방은 창문으로 찬 공기가 들어와서 난방을 켜도 잘 따뜻해지지 않아요. 지난달에 청구서를 봤더니 전기요금이 평소보다 많이 나와서 깜짝 놀랐어요. 친구에게 이야기했더니 절약 요령을 여러 가지 알려 주었어요.","먼저 전기담요를 써서 자기 전에 이불을 따뜻하게 해 둬요. 가습기를 켜면 방 온도가 같아도 더 따뜻하게 느껴진다고 해요. 두꺼운 커튼으로 바꿨더니 창가의 차가운 기운이 꽤 줄었어요. 난방 설정 온도를 조금 낮게 하고, 겉옷을 입고 지내고 있어요.","다나카 씨는 쓰지 않는 방은 난방을 끄는 게 좋다고 알려 주었어요. 요금제에 대해서는 자세한 내용을 전력 회사에 물어보는 게 좋아요. 작은 노력을 계속하면 추운 겨울도 전기요금을 너무 신경 쓰지 않고 지낼 수 있을 것 같아요."],"vocab":["난방","찬 공기","청구서","전기요금","절약","전기담요","가습기","두꺼운","설정 온도","궁리, 아이디어"],"grammar":[{"t":"〜たら","note":"'~했더니(알게 되었다)' 또는 가정 조건을 나타내요. 예: 「請求書を見たら、電気代がいつもより高くて」「厚いカーテンに換えたら、窓の近くの冷たさがかなり減りました」"},{"t":"可能形","note":"'~할 수 있다'를 나타내요. 예: 「あたたかく感じられる」「過ごせそうです」. 1단 동사는 「られる」를 붙이고, 5단 동사는 끝소리를 え단으로 바꾸고 「る」를 붙여요."},{"t":"〜そうだ","note":"두 가지 용법이 있어요. 보통형에 붙으면 '~라고 한다(전문)', 동사 ます형에서 ます를 뺀 형태에 붙으면 '~할 것 같다(양태)'예요. 예: 「あたたかく感じられるそうです」(전문), 「過ごせそうです」(양태)"},{"t":"〜てもらう/〜てくれる","note":"다른 사람이 나를 위해 어떤 일을 해 주는 것을 나타내요(수수 표현). 예: 「いろいろ教えてもらいました」「教えてくれました」. 〜てもらう는 자신이 주어이고, 〜てくれる는 상대방이 주어예요."}]},"eh-n5-2":{"title":"역에서 길을 잃었어요","topic":"그림책","trans":["오늘은 날씨가 아주 좋아요. 타누타로는 전철을 타고 바다에 가요.","역이 아주 커요. 사람도 많아요. 바다로 가는 전철은 몇 번 승강장일까요? 타누타로는 잘 몰라요.","지도를 봤지만 오히려 더 헷갈렸어요. 타누타로는 난감했어요.","그때 여우 コン이 왔어요. \"무슨 일이에요?\" 하고 물었어요.","타누타로는 \"실례합니다, 바다로 가는 전철은 어디예요?\" 하고 물었어요.","コン은 \"3번 승강장이에요. 저기 계단으로 올라가세요.\" 하고 알려 줬어요.","타누타로는 \"고맙습니다\" 하고 말한 뒤 달려갔어요. 전철을 시간 안에 탔어요!"],"vocab":[{"w":"駅","m":"역"},{"w":"迷子","m":"길을 잃음, 길 잃은 사람"},{"w":"電車","m":"전철"},{"w":"番線","m":"~번 승강장"},{"w":"地図","m":"지도"},{"w":"困る","m":"곤란하다, 난처하다"},{"w":"階段","m":"계단"},{"w":"上る","m":"올라가다"},{"w":"教える","m":"알려 주다, 가르치다"},{"w":"間に合う","m":"시간에 맞추다, 늦지 않다"}],"grammar":[{"t":"〜てください","note":"동사의 て형+ください로, 상대에게 정중하게 부탁하거나 요청할 때 써요. 예: あそこの かいだんを のぼって ください。"},{"t":"의문사(どこ・何)","note":"장소를 물을 때는 「どこ」, 번호를 물을 때는 「何ばんせん」을 써요. 예: うみへ 行く でんしゃは どこですか。"},{"t":"〜くなります","note":"い형용사에서 い를 빼고 くなります를 붙이면 '~해지다'라는 뜻이에요. ない도 마찬가지예요: わからない→わからなく なりました(더 모르게 되었어요)."}]},"eh-n4-1":{"title":"감기에 걸린 날","topic":"그림책","trans":["아침에 일어나니 머리가 아프고 목도 많이 아팠어요. 열도 나는 것 같아요.","타누타로는 회사에 전화해서 \"죄송합니다, 감기에 걸려서 오늘은 쉬겠습니다\" 하고 말했어요.","그러고 나서 근처 병원에 갔어요. 접수처에서 건강보험증을 내고 문진표를 썼어요.","의사 선생님이 \"언제부터예요?\" 하고 물었어요. \"어젯밤부터고, 기침도 나요\" 하고 대답했어요.","의사 선생님이 \"그냥 감기예요. 약을 먹고 푹 쉬는 게 좋아요\" 하고 말했어요.","그날 밤 コン이 죽을 가져다줬어요. 따뜻하고 아주 맛있었어요.","사흘 뒤 타누타로는 완전히 기운을 되찾았어요. 일본에서 병원에 가는 건 조금 무서웠지만, 이제 괜찮아요."],"vocab":[{"w":"熱","m":"열"},{"w":"休む","m":"쉬다, 결근하다"},{"w":"受付","m":"접수처"},{"w":"保険証","m":"건강보험증"},{"w":"問診票","m":"문진표"},{"w":"お医者さん","m":"의사 선생님"},{"w":"薬","m":"약"},{"w":"おかゆ","m":"죽"},{"w":"すっかり","m":"완전히, 말끔히"},{"w":"元気","m":"건강함, 기운이 있음"}],"grammar":[{"t":"〜ので","note":"원인이나 이유를 나타내요. 「から」보다 부드러워서 휴가를 요청하거나 사과할 때 자주 써요. 예: かぜをひいたので、今日は休ませてください。"},{"t":"〜ほうがいいです","note":"동사의 た형+ほうがいいです로, 상대에게 '~하는 편이 좋다'고 조언할 때 써요. 예: ゆっくり休んだほうがいいですよ。"},{"t":"수동형","note":"「(사람)に〜られる」는 다른 사람에게 어떤 행동을 당했다는 뜻이에요. 예: お医者さんに「いつからですか」と聞かれました。"},{"t":"〜てくれます","note":"다른 사람이 나를 위해 무언가를 해 줄 때 써요(고마운 마음이 담겨요). 예: コンちゃんがおかゆを持ってきてくれました。"}]},"a-n2-12":{"title":"근로감사의 날을 생각하다","topic":"사회","trans":["11월 23일은 「勤労感謝の日」로, 해마다 이날은 많은 회사와 학교가 쉬는 국민 공휴일이에요. 이름만 보면 일하는 사람을 위한 날이라고 생각하기 쉽지만, 원래 유래는 조금 달라요. 일본에서는 예로부터 가을에 그해 수확한 햇곡식을 신에게 바치며 감사하는 「新嘗祭」라는 의식을 치러 왔어요. 新嘗祭는 수확을 축하하고 자연의 은혜에 감사하는 행사로, 농업을 소중히 여겨 온 사회의 생각을 보여 줘요.","전쟁 이후 나라의 제도가 크게 재검토되는 가운데 공휴일의 모습도 정리하게 되었어요. 1948년에 「국민 공휴일에 관한 법률」이 제정되면서 이날은 「勤労感謝の日」라는 이름의 국민 공휴일이 되었어요. 법에는 근로를 소중히 여기고, 생산을 축하하며, 국민이 서로 감사하는 날이라는 취지가 담겨 있어요. 신에 대한 감사가 일하고 만드는 일 자체에 대한 감사로 넓어졌다고 생각하면 이해하기 쉬워요.","현대에는 일하는 방식이 다양해짐에 따라 「勤労」라는 말에서 떠올리는 모습도 달라졌어요. 공장이나 논밭에서 일하는 사람은 물론이고, 가게, 물류, 의료, 돌봄 등 생활을 떠받치는 일은 셀 수 없이 많아요. 게다가 이런 일 중에는 공휴일에도 쉬기는커녕 평소보다 더 많이 일할 수밖에 없는 일도 있어요. 우리가 당연하게 누리는 편리함은 이런 사람들의 노력 위에서 이루어지는 거예요.","그렇다면 감사를 행동으로 옮기려면 어떻게 하면 좋을까요? 짐을 배달해 준 사람이나 점원에게 「ありがとうございます」라고 한마디 건네는 것만으로도 마음은 충분히 전해져요. 직장에서도 동료의 업무 태도를 인정하고 고마움을 표현하는 것은 이날을 계기로 바로 시작할 수 있는 작은 습관이에요. 참고로 공휴일의 근무와 휴무 처리는 회사마다 다르니, 자세한 내용은 회사의 안내를 확인하세요. 감사하는 마음은 공휴일 하루만이 아니라 매일의 생활 속에서 말로 표현할 때 비로소 의미가 있지 않을까요?"],"vocab":[{"w":"由来","m":"유래, 기원"},{"w":"新嘗祭","m":"니이나메사이(햇곡식의 수확에 감사하는 제사)"},{"w":"収穫","m":"수확"},{"w":"制度","m":"제도"},{"w":"趣旨","m":"취지"},{"w":"多様","m":"다양함"},{"w":"物流","m":"물류"},{"w":"支える","m":"떠받치다, 지탱하다"},{"w":"成り立つ","m":"성립하다, ~ 위에 이루어지다"}],"grammar":[{"t":"〜に伴って","note":"어떤 변화에 따라 다른 일도 함께 변한다는 뜻이에요. 예:「働き方が多様になるに伴って、『勤労』という言葉から思い浮かべる姿も変わってきた」"},{"t":"〜どころか","note":"'~은커녕 오히려 ~'라는 뜻으로, 앞의 내용을 부정하고 뒤의 내용을 강조해요. 예:「祝日であっても休むどころか、いつも以上に働かざるを得ない」"},{"t":"〜ざるを得ない","note":"'~할 수밖에 없다'라는 뜻으로, 상황 때문에 다른 선택지가 없을 때 써요. 예:「いつも以上に働かざるを得ないものもある」"},{"t":"〜をきっかけに","note":"어떤 일을 계기로 무언가를 시작한다는 뜻이에요. 예:「この日をきっかけにすぐ始められる小さな習慣である」"}]},"a-n5-14":{"title":"친구와 전골","topic":"생활","trans":["겨울의 어느 날, 친구와 집에서 전골을 해 먹었어요. 먼저 다 같이 슈퍼에 갔어요. 배추와 두부와 고기를 샀어요.","집에서 채소를 썰어서 냄비에 넣었어요. 채소를 먼저 넣고, 고기는 나중에 넣었어요. 방이 따뜻해졌어요.","다 같이 함께 먹으니 맛있어요. 추운 밤이었지만 즐거웠어요."],"vocab":[{"w":"冬","m":"겨울"},{"w":"なべ","m":"냄비; 전골"},{"w":"スーパー","m":"슈퍼마켓"},{"w":"はくさい","m":"배추"},{"w":"とうふ","m":"두부"},{"w":"肉","m":"고기"},{"w":"入れる","m":"넣다"},{"w":"先に","m":"먼저"},{"w":"あたたかい","m":"따뜻하다"},{"w":"みんな","m":"모두, 다들"}],"grammar":[{"t":"〜て、〜(動詞て形)","note":"て형으로 두 동작을 이어서, 앞의 동작을 하고 나서 뒤의 동작을 한다는 뜻을 나타내요. 예:「やさい を 切って、なべ に 入れました。」"},{"t":"〜と、〜","note":"'~하면 ~하다'라는 뜻으로, 일반적인 결과나 느낌을 나타내요. 예:「いっしょ に たべる と、おいしい です。」"},{"t":"〜く なります","note":"い형용사를 「〜く」로 바꾸고 「なります」를 붙여 상태의 변화를 나타내요. 예:「へや が あたたかく なりました。」"},{"t":"〜が、〜","note":"문장 끝에 붙여 '~지만 ~'라는 뜻으로 상반되는 내용을 이어요. 예:「さむい よる でした が、たのしかった です。」"}]},"eh-n4-2":{"title":"라멘집에서","topic":"그림책","trans":["역 근처에 인기 있는 라멘집이 있어요. 오늘 타누타로는 처음으로 그곳에 들어갔어요.","입구에 식권 발매기가 있었어요. 이 가게에서는 먼저 식권을 산대요.","그런데 버튼이 너무 많아서 어느 것을 눌러야 할지 모르겠어요.","그때 뒤에 있던 콘이 \"맨 왼쪽이 보통 라멘이야.\" 하고 알려 줬어요.","자리에 앉아 식권을 건네자 점원이 \"면 굵기는 어떻게 해 드릴까요?\" 하고 물었어요.","타누타로는 \"조금 딱딱하게 해 주세요.\" 하고 대답했어요. 「かため」는 면이 조금 딱딱한 것을 말해요.","뜨거운 국물과 꼬들꼬들한 면은 최고였어요. 타누타로는 국물을 전부 마셔 버렸어요."],"vocab":["인기","입구","식권 발매기","식권","누르다, 밀다","보통","자리, 좌석","건네다, 넘겨주다","면","전부"],"grammar":[{"t":"〜そうです(伝聞)","note":"보통형+そうです는 \"~라고 해요, ~대요\"라는 뜻이에요. 예: この店では、先に食券を買うそうです。"},{"t":"〜ばいい","note":"「どれを〜ばいいか」는 \"어느 것을 ~하면 좋을지\"라는 뜻이에요. 예: どれを押せばいいかわかりません。"},{"t":"〜てしまいます","note":"동작을 완전히 끝냈다는 뜻이에요. \"그만 ~해 버렸다\"라는 뉘앙스로도 자주 써요. 예: スープを全部飲んでしまいました。"},{"t":"〜と(条件)","note":"「A と、B」는 \"A를 하면 B가 일어난다\"라는 뜻이에요. 예: 食券を渡すと、店員さんに聞かれました。"}]},"eh-n4-3":{"title":"비 오는 날의 선물","topic":"그림책","trans":["다음 주 토요일은 콘의 생일이에요. 콘이 늘 하고 다니는 파란 목도리는 이미 꽤 낡았어요.","타누타로는 새 목도리를 선물하기로 마음먹었어요. 그런데 그날은 아침부터 비가 내렸어요.","타누타로는 우산을 쓰고 동네 잡화점에 갔어요. 그곳에서 예쁜 파란 목도리를 발견했어요.","조금 비쌌지만 타누타로는 그걸 사기로 했어요. 점원이 예쁘게 포장해 줬어요.","돌아오는 길에 비가 더 세게 내렸어요. 타누타로는 선물이 젖지 않도록 가방을 꼭 끌어안고 달렸어요.","\"생일 축하해.\" 하며 선물을 건네자 콘은 깜짝 놀랐어요.","새 목도리를 두른 콘은 \"고마워, 오래오래 소중히 쓸게.\" 하고 웃었어요."],"vocab":["생일","목도리","우산","잡화점","발견하다, 찾다","싸다, 포장하다","젖다","끌어안다, 안아 들다","놀라다","소중하다, 중요하다"],"grammar":[{"t":"〜うと思います","note":"동사 의지형+と思います는 \"~하려고 해요, ~할 생각이에요\"라는 뜻으로, 스스로 무언가를 하려고 마음먹었을 때 써요. 예: 新しいマフラーをプレゼントしようと思いました。"},{"t":"〜ことにします","note":"동사 사전형+ことにします는 스스로 \"~하기로 정했다\"는 뜻이에요. 예: それを買うことにしました。"},{"t":"〜ように(目的)","note":"「A ように、B」는 \"A가 되도록 B를 한다\"는 뜻이에요. 앞에는 ない형이나 가능형이 자주 와요. 예: プレゼントがぬれないように、かばんをしっかり抱えて走りました。"},{"t":"〜てくれます","note":"다른 사람이 나를 위해 무언가를 해 준다는 뜻이에요. 예: 店員さんがきれいに包んでくれました。"}]},"a-n3-16":{"title":"상중 엽서가 도착했을 때","topic":"문화","trans":["11월 초, 회사 동료 다나카 씨에게서 엽서 한 장이 왔어요. 열어 보니 「喪中につき、年始のご挨拶をご遠慮申し上げます」라고 적혀 있었어요. 다나카 씨의 아버지가 올여름에 돌아가신 사실을 저는 그때 처음 알았어요.","이것은 「喪中はがき」라고 해요. 가족이 상을 당한 사람이 연하장을 보내지 않겠다고 알리는 엽서예요. 상을 치르는 동안에는 축하할 일을 삼가야 한다는 생각에서 이런 관습이 생겼어요. 이 엽서는 연하장 준비가 시작되기 전에 도착하는 경우가 많은데, 상대에게 미리 알리기 위해서예요. 상중 엽서는 '저는 연하장을 보낼 수 없어요'라고 알리는 것일 뿐, 답장을 바라는 것은 아니에요.","저는 조금 망설였지만 동료에게 물어보고 다나카 씨에게는 연하장을 보내지 않기로 했어요. 대신 해가 바뀌고 얼마 지난 뒤에 「寒中見舞い」를 보내면 마음이 전해진다고 동료가 알려 줬어요. 寒中見舞い는 추운 계절에 상대의 건강을 걱정하며 보내는 인사장으로, 축하의 말은 쓰지 않아요. 저는 엽서를 받아서 고맙다는 말과 다나카 씨의 가족을 생각하는 말을 넣으려고 신경 썼어요.","연하장을 어떻게 다루는지는 직장마다 달라요. 자세한 내용은 회사의 안내를 확인해 두세요. 연하장을 보내는 관습은 조금씩 줄고 있지만, 계절 인사로 마음을 전하는 문화는 지금도 소중하게 여겨져요. 이번 경험을 통해 상대의 상황을 헤아려 인사의 형식을 바꾸는 것도 직장에서 중요한 예절이라는 것을 배웠어요."],"vocab":[{"w":"喪中","m":"상중, 상을 치르는 기간"},{"w":"年賀状","m":"연하장"},{"w":"亡くなった","m":"돌아가셨다, 세상을 떠났다"},{"w":"挨拶","m":"인사"},{"w":"遠慮","m":"사양, 삼가기"},{"w":"控える","m":"삼가다, 자제하다"},{"w":"寒中見舞い","m":"한중 인사(추운 계절에 보내는 안부 인사장)"},{"w":"気づかう","m":"걱정하다, 마음을 쓰다"},{"w":"習慣","m":"습관, 관습"},{"w":"心がけた","m":"유념했다, 신경 썼다"}],"grammar":[{"t":"〜ことにする","note":"스스로 어떤 일을 하기로 결정했다는 뜻이에요. 예: 「田中さんには年賀状を出さないことにした。」"},{"t":"〜わけではない","note":"'~라는 것은 아니다'라는 뜻으로, 부분 부정이나 오해를 바로잡을 때 써요. 예: 「返事を求めているわけではない。」"},{"t":"〜ように心がける","note":"어떤 목표를 이루기 위해 노력하고 유의한다는 뜻이에요. 예: 「お礼と、田中さんの家族を思う言葉を入れるように心がけた。」"},{"t":"〜によって違う","note":"'~에 따라 다르다'라는 뜻이에요. 예: 「会社の年賀状の扱いは職場によって違う。」"}]},"a-n4-15":{"title":"연말 대청소, 일찍 시작해요","topic":"생활","trans":["매년 12월이 되면 대청소가 힘들어서 늘 지쳐 버려요. 올해는 12월이 되기 전에 청소할 곳을 목록으로 적어 봤어요. 주방, 욕실, 창문, 현관 등 여러 군데가 있었어요.","다음으로 드러그스토어에서 세제와 스펀지를 샀어요. 가게 직원이 욕실용 세제는 곰팡이도 지울 수 있다고 알려 줬어요. 한꺼번에 다 하면 지치니까 매주 한 곳만 청소하기로 했어요. 이번 주는 주방, 다음 주는 욕실, 이런 식으로 정했어요.","룸메이트 린 씨에게도 이야기했더니 같이 하자고 했어요. 저는 주방과 욕실, 린 씨는 창문과 현관을 맡아요. 큰 쓰레기는 버리는 방법을 구청 안내문으로 확인해야 해요. 친구 말로는 일찍 시작하면 마음도 편해진대요. 이 방법이라면 연말에도 여유롭게 쉴 수 있을 것 같아요."],"vocab":[{"w":"大そうじ","m":"대청소"},{"w":"年末","m":"연말"},{"w":"台所","m":"주방, 부엌"},{"w":"洗剤","m":"세제"},{"w":"毎週","m":"매주"},{"w":"一度に","m":"한꺼번에, 동시에"},{"w":"担当","m":"담당"},{"w":"区役所","m":"구청"},{"w":"気持ち","m":"기분, 마음"}],"grammar":[{"t":"〜たら","note":"'~했더니', '~하면'이라는 뜻으로, 어떤 일을 한 뒤의 전개나 조건을 나타내요. 본문 예: 「ルームメイトのリンさんにも話したら、いっしょにやると言ってくれました。」"},{"t":"가능형","note":"'~할 수 있다'라는 뜻이에요. 본문 예: 「おふろ用の洗剤はカビも落とせると教えてくれました。」(落とす→落とせる), 「ゆっくり休めそうだ」(休む→休める)"},{"t":"〜てくれる(수수 표현)","note":"다른 사람이 나를 위해 어떤 일을 해 준다는 뜻으로, 고마운 마음이 담겨 있어요. 본문 예: 「店の人が、…教えてくれました。」「いっしょにやると言ってくれました。」"},{"t":"〜そうだ","note":"두 가지 용법이 있어요. ① 동사 ます형에서 ます를 뺀 형태에 붙으면 '~할 것 같다'(양태)라는 뜻이에요. 예: 「休めそうだ」 ② 보통형에 붙으면 전해 들은 이야기(전문)를 나타내요. 예: 「気持ちも楽になるそうです」"}]},"a-n2-13":{"title":"변해 가는 송년회, 변하지 않는 배려","topic":"직장","trans":["연말이 가까워지면 일본 직장에서는 예로부터 자연스럽게 '보넨카이(송년회)' 이야기가 나오곤 했어요. 한 해의 고생을 잊고 친목을 다진다는 의미가 있어서, 예전에는 참석하는 것이 당연하다고 여겼죠. 그런데 최근에는 퇴근 후 시간을 자신을 위해 쓰고 싶어서 참석을 원하지 않는 사람이 늘고 있어요. 이에 따라 밤 회식을 없애고 점심 모임으로 바꾸거나 참석을 자율에 맡기는 회사도 눈에 띄게 늘었어요.","배경에는 가치관의 다양화와, 가정이나 간병과의 병행을 우선하고 싶다는 사정이 있어요. 상사와 함께하는 자리가 편하게 즐겁기는커녕 신경 쓰느라 피곤하기만 하다고 느끼는 젊은 직원도 적지 않아요. 한편 평소에는 이야기하기 어려운 동료와 교류할 수 있는 소중한 기회라고 생각해서 모임을 반기는 사람이 있는 것도 사실이에요. 회사 입장에서는 강제하면 불만이 커질 수 있기 때문에, 저마다의 사정을 배려한 방식을 찾을 수밖에 없어요.","초대를 받고 거절할 때는 먼저 초대해 준 데 대한 감사를 전하는 것이 기본이에요. 예를 들어 「お誘いありがとうございます。あいにく先約がありまして」라고 거절하면 분위기가 어색해지지 않아요. 이유를 너무 자세히 설명하면 변명처럼 들릴 수도 있으니, 간단히 전하고 「またの機会にぜひ」라고 덧붙이면 좋아요. 반대로 참석할 때도 술을 못 마시면 우롱차로 건배해도 되고, 일찍 돌아간다는 점을 처음에 전해 두면 마음이 편해요.","참석하지 않는 사람을 냉정하다고 보거나, 참석하는 사람을 그저 사교성이 좋을 뿐이라고 단정 짓는 일은 피하고 싶어요. 총무 쪽에서도 안내문을 보낼 때 「参加は自由です」라고 한마디 덧붙이면, 거절하는 쪽의 심리적 부담이 훨씬 가벼워져요. 중요한 것은 형식 자체보다 서로의 사정과 마음을 존중하려는 자세가 아닐까요? 송년회가 점심 모임으로 바뀌어도 사람과 사람 사이의 신뢰를 키우는 자리라는 점은 변함이 없어요."],"vocab":["송년회","친목, 친목 다지기","가치관","양립, 병행","강제","배려","선약","간사, 행사 주최자","존중"],"grammar":[{"t":"〜に伴って","note":"어떤 일이 변하면 그에 따라 다른 일도 함께 변한다는 뜻이에요. 예: 「それに伴って、夜の宴会をやめて昼のランチ会にしたり…する会社も目立つようになった」."},{"t":"〜どころか","note":"'~은커녕, 오히려 ~'라는 뜻으로, 앞의 내용을 부정하고 반대되거나 더 극단적인 사실을 말해요. 예: 「気楽に楽しめるどころか、気を使って疲れるだけだと感じる」."},{"t":"〜かねない","note":"동사 ます형에서 ます를 뺀 형태에 붙어 '(좋지 않은 일이) 일어날 수 있다'는 뜻을 나타내요. 예: 「強制すれば不満が高まりかねない」."},{"t":"〜ざるを得ない","note":"'~할 수밖에 없다'라는 뜻으로, 달리 선택지가 없어 그렇게 해야 할 때 써요. 예: 「それぞれの事情に配慮した形を探さざるを得ない」."}]},"eh-n5-1":{"title":"처음 가 본 편의점","topic":"그림책","trans":["타누타로는 어제 일본에 왔어요. 오늘은 처음으로 편의점에 가요.","가게 안은 아주 밝아요. 주먹밥이랑 빵, 음료수가 아주 많이 있어요.","타누타로는 도시락 하나와 차 한 병을 골랐어요. 계산대로 가져가요.","점원이 「あたためますか」라고 물었어요. 타누타로는 무슨 뜻인지 몰라요.","「あたためますか」는 '뜨겁게 해 드릴까요?'라는 뜻이에요. 타누타로는 '네, 부탁합니다'라고 말했어요.","다음으로 점원이 '봉투 필요하세요?'라고 물었어요. 이번에는 알아들었어요. '괜찮아요'라고 대답했어요.","따뜻한 도시락은 아주 맛있었어요. 타누타로는 또 편의점에 가고 싶어요."],"vocab":["편의점","처음","도시락","고르다","계산대","점원","데우다, 따뜻하게 하다","의미, 뜻","봉투","대답하다"],"grammar":[{"t":"〜という","note":"「A という いみです」는 'A는 ~라는 뜻이에요'라는 의미로, 단어를 설명할 때 써요. 예: 「あたためますか」は「あつく しますか」と いう いみです。"},{"t":"〜たいです","note":"동사 ます형에서 ます를 뺀 형태에 たいです를 붙여 '~하고 싶어요'라는 뜻을 나타내요. 예: また コンビニに 行きたいです。"},{"t":"〜と(나열)","note":"명사と명사로 물건을 빠짐없이 나열해요. '~와/과'에 해당해요. 예: おべんとうを 一つと おちゃを 一つ。"}]},"a-n2-7-n3":{"title":"そなえあれば","topic":"생활","trans":["일본은 지진이나 태풍 같은 자연재해가 많은 나라로 알려져 있어요. 언제 일어날지 모르는 재해이기 때문에 평소에 미리 대비해 두는 것이 중요해요.","먼저 집에서 할 수 있는 일부터 시작해 봐요. 물과 식량, 손전등 등을 준비해 두면 만약의 순간에 안심할 수 있어요. 이런 물건은 바로 들고 나갈 수 있는 곳에 두도록 해요.","가족과 미리 이야기해 두는 것도 잊어서는 안 돼요. 재해가 일어났을 때 가족이 뿔뿔이 흩어질 수도 있기 때문이에요. 어디에서 모일지 정해 두면 당황하지 않고 행동할 수 있어요. 또 사는 지역의 위험한 장소를 알아 두는 것도 도움이 돼요. 시청 등에서 나눠 주는 지도를 보고 대피소까지 가는 길을 확인해 두세요.","재해 자체를 막을 수는 없어도 피해를 줄일 수는 있어요. 평소의 작은 마음가짐 덕분에 만약의 순간에 나와 가족을 지킬 수 있답니다."],"vocab":["자연재해","평소, 평상시","대비하다, 준비하다","준비","손전등","들고 나가다, 꺼내 가다","뿔뿔이 흩어지다, 놓치다","대피소","피해","마음가짐, 유념"],"grammar":[{"t":"〜だからこそ","note":"'바로 ~이기 때문에 더욱 ……'라는 뜻으로, 이유를 강조할 때 써요. 예: 「いつ起こるか分からない災害だからこそ、日ごろから備えておくことが大切です」."},{"t":"〜ておく","note":"나중을 위해 미리 어떤 일을 해 두는 것을 나타내요. 예: 「水や食料、懐中電灯などを用意しておくと、いざというときに安心です」."},{"t":"〜ようにする","note":"어떤 습관을 들이려고 노력하거나 되도록 그렇게 하려 한다는 뜻이에요. 예: 「すぐに持ち出せる場所に置いておくようにしましょう」."},{"t":"〜によって","note":"수단이나 원인을 나타내며 '~에 의해, ~을 통해'라는 뜻이에요. 예: 「ふだんのちょっとした心がけによって、いざというときに自分や家族を守ることができるのです」."}]},"a-n2-7-n4":{"title":"災害にそなえよう","topic":"생활","trans":["일본은 지진이나 태풍 같은 자연재해가 많은 나라예요. 언제 올지 모르기 때문에 평소부터 준비해 두는 것이 중요해요.","먼저 집에서 할 수 있는 일부터 시작해요. 물과 음식, 손전등을 준비해 두면 안심이 돼요. 바로 들고 나갈 수 있는 곳에 두세요. 가족과 이야기해서 서로 흩어졌을 때 모일 장소도 정해 두세요.","사는 동네의 위험한 곳을 알아 두는 것도 중요해요. 시청의 지도를 보고 대피소까지 가는 길을 미리 확인해 두세요. 재해는 막을 수 없어도 피해를 줄일 수는 있어요. 평소의 작은 마음가짐이 나와 가족을 지켜 줘요."],"vocab":["지진","태풍","준비","중요함, 소중함","안심","준비, 채비","의논하다, 상의하다","정하다","위험","대피소"],"grammar":[{"t":"〜ておく","note":"미리 어떤 일을 해 두는 것을 나타내요. 예: 「ふだんから準備しておくことが大切です」「決めておきましょう」."},{"t":"〜ので","note":"원인·이유를 나타내며 「から」보다 부드러운 느낌이에요. 예: 「いつ来るか分からないので、ふだんから準備しておくことが大切です」."},{"t":"〜ましょう","note":"상대에게 함께 하자고 권하거나 제안할 때 써요. 예: 「まず、家でできることから始めましょう」."},{"t":"〜ても/〜ことができる","note":"「〜ても」는 '~해도'라는 뜻이고, 「ことができる」는 '~할 수 있다'라는 뜻이에요. 예: 「災害は防げなくても、被害を少なくすることはできます」."}]},"a-n2-5-n3":{"title":"확산되는 캐시리스 결제","topic":"사회","trans":["최근 몇 년 사이 일본에서도 캐시리스 결제를 이용하는 사람이 갑자기 크게 늘었어요. 예전에는 현금만 받는 가게가 많았지만, 지금은 스마트폰이나 카드로 결제할 수 있는 가게가 점점 늘고 있어요.","캐시리스 결제는 결제가 빠르고 돈 관리가 쉽다는 장점이 있어요. 계산대에서 동전을 찾을 필요가 없어서 쇼핑 시간이 짧아져요. 또 언제, 얼마를 썼는지가 기록으로 남기 때문에 나중에 확인하기도 쉬워요.","한편, 아직 해결해야 할 문제도 있어요. 정전이나 통신 장애가 생기면 결제를 못 하게 될 우려가 있어요. 자기도 모르게 너무 많이 쓰는 사람도 있고, 기계 조작이 서툰 고령자도 있어요. 그래서 이런 사람들에 대한 배려도 잊어서는 안 돼요.","편리함과 안심 사이의 균형을 어떻게 잡아야 할까요? 현금과 캐시리스를 둘 다 잘 활용하는 사회가 필요해요."],"vocab":[{"w":"決済","m":"결제"},{"w":"急に","m":"갑자기, 급격히"},{"w":"管理","m":"관리"},{"w":"小銭","m":"동전, 잔돈"},{"w":"記録","m":"기록"},{"w":"停電","m":"정전"},{"w":"障害","m":"장애, 고장"},{"w":"操作","m":"조작"},{"w":"高齢者","m":"고령자"},{"w":"配慮","m":"배려"}],"grammar":[{"t":"〜やすい","note":"동사의 ます형에 붙어서 '~하기 쉽다'는 뜻을 나타내요. 예: 「お金の管理がしやすい」「後で確認しやすい」."},{"t":"〜ため(원인)","note":"원인과 이유를 나타내며, 「から」보다 글말에 가까운 표현이에요. 예: 「小銭を探す必要がないため、買い物の時間が短くなる」."},{"t":"〜おそれがある","note":"좋지 않은 일이 일어날 가능성이 있다는 뜻이에요. 예: 「支払いができなくなるおそれがある」."},{"t":"〜なければならない","note":"'~해야 한다'는 뜻을 나타내요. 예: 「まだ解決しなければならない問題もある」."}]},"a-n2-5-n4":{"title":"확산되는 캐시리스","topic":"사회","trans":["최근 일본에서도 캐시리스로 결제하는 사람이 빠르게 늘었어요. 예전에는 현금만 받는 가게가 많았어요. 지금은 스마트폰이나 카드로 결제할 수 있는 가게가 늘고 있어요.","캐시리스는 결제가 빠르고 돈 관리도 간단해요. 계산대에서 동전을 찾지 않아도 되기 때문이에요. 언제, 얼마를 썼는지도 기록으로 남아요.","하지만 아직 문제가 되는 부분도 있어요. 정전이나 통신 문제가 생기면 결제를 못 하게 될지도 몰라요. 너무 많이 쓰는 사람이나 기계가 서툰 어르신도 생각해야 해요. 현금과 캐시리스를 둘 다 쓸 수 있는 사회가 중요해요."],"vocab":[{"w":"現金","m":"현금"},{"w":"払う","m":"지불하다, 결제하다"},{"w":"増える","m":"늘다, 증가하다"},{"w":"小銭","m":"동전, 잔돈"},{"w":"管理","m":"관리"},{"w":"記録","m":"기록"},{"w":"停電","m":"정전"},{"w":"機械","m":"기계"},{"w":"お年寄り","m":"어르신, 노인"},{"w":"社会","m":"사회"}],"grammar":[{"t":"〜なくてもいい","note":"'~하지 않아도 된다'는 뜻을 나타내요. 예: 「レジで小銭を探さなくてもいいからです」"},{"t":"〜かもしれません","note":"'~일지도 모른다', '~할 수도 있다'는 뜻을 나타내요. 예: 「払えなくなるかもしれません」"},{"t":"〜なければなりません","note":"'~해야 한다'는 뜻을 나타내요. 예: 「お年寄りのことも考えなければなりません」"},{"t":"動詞ます형+すぎる","note":"'너무 ~하다', '지나치게 ~하다'는 뜻을 나타내요. 예: 「使いすぎる人」"}]},"a-n3-1-n2":{"title":"생활을 지탱하는 편의점의 편리함","topic":"생활","trans":["일본의 편의점은 24시간 영업해서 언제든 이용할 수 있는 간편함이 큰 매력이에요. 음식과 음료는 물론 잡지와 생활용품까지 살 수 있어서, 생활에 필요한 물건을 거의 한 곳에서 다 구할 수 있어요. 단순한 식료품점이라기보다는 생활을 지탱하는 친숙한 시설이라고 할 수 있을 거예요.","게다가 공과금 납부나 택배 발송처럼 생활에 꼭 필요한 업무까지 처리할 수 있어요. 은행 ATM이 설치되어 있어서 필요할 때는 언제든 돈을 찾을 수 있어요. 복사나 티켓 예매를 할 수 있는 기계도 놓여 있어서, 편의점의 역할은 쇼핑에만 그치지 않아요.","이런 서비스가 충실해진 덕분에 편의점은 우리 생활에 없어서는 안 될 존재가 되었어요. 바빠서 시간이 없는 사람에게는 짧은 시간에 볼일을 끝낼 수 있는 곳이 있다는 것이 큰 도움이에요. 요즘은 편의점 없는 생활을 상상하는 것조차 어렵다고 느끼는 사람도 적지 않을 거예요.","하지만 그 편리함의 이면에는 24시간 일하는 사람들의 고충과 식품 폐기 같은 문제가 숨어 있어요. 언제든 가게가 열려 있다는 것은 밤에도 누군가는 계속 일해야 한다는 뜻이기도 해요. 우리는 편리함을 당연하게 여기기 쉽지만, 그것은 많은 사람의 노력이 있어야 비로소 성립해요. 편리함을 누리기만 할 것이 아니라 그 시스템을 지탱하는 사람들에게도 눈을 돌리고 싶어요."],"vocab":[{"w":"手軽さ","m":"간편함, 손쉬움"},{"w":"公共料金","m":"공공요금(전기·수도·가스 등)"},{"w":"発送","m":"발송"},{"w":"手続き","m":"수속, 절차"},{"w":"設置","m":"설치"},{"w":"充実","m":"충실, 알참"},{"w":"欠かせない","m":"없어서는 안 되는"},{"w":"食品ロス","m":"식품 폐기, 음식물 낭비"},{"w":"当たり前","m":"당연함"},{"w":"支える","m":"지탱하다, 떠받치다"}],"grammar":[{"t":"〜にとどまらない","note":"「～에 그치지 않는다」라는 뜻으로, 범위가 생각보다 넓다는 걸 나타내요. 예:「店の役割は買い物だけにとどまらない」."},{"t":"〜といった","note":"대표적인 예를 들 때 쓰며「～와 같은」이라는 뜻이에요. 예:「食品ロスといった問題が隠れている」."},{"t":"〜がちだ","note":"동사 ます형에서 ます를 뺀 형태에 붙어, 좋지 않은 경향이 자주 나타남을 뜻해요.「～하기 쉽다, ～하는 경향이 있다」. 예:「便利さを当たり前のものと考えがちだ」."},{"t":"〜て初めて","note":"「～하고 나서야 비로소 ～하다」라는 뜻으로, 앞의 내용이 필수 조건임을 강조해요. 예:「多くの人の努力があって初めて成り立っている」."}]},"a-n3-1-n4":{"title":"편의점의 편리함","topic":"생활","trans":["일본의 편의점은 24시간 열려 있어서 아주 편리해요.","음식과 음료뿐 아니라 잡지와 생활용품도 살 수 있어요. 게다가 공과금을 내거나 짐을 보낼 수도 있어요.","은행 ATM도 있어서 언제든 돈을 찾을 수 있어요. 복사나 티켓 예매를 할 수 있는 기계도 있어요. 이런 서비스 덕분에 편의점은 생활에 중요한 존재가 되었어요.","하지만 편리함 뒤에는 문제도 있어요. 24시간 일하는 사람은 아주 힘들어요. 음식이 버려지는 식품 폐기 문제도 있어요. 편리함을 당연하게 생각하지 말고, 일하는 사람들도 생각하고 싶어요."],"vocab":[{"w":"便利","m":"편리함"},{"w":"雑誌","m":"잡지"},{"w":"日用品","m":"생활용품"},{"w":"公共料金","m":"공공요금(전기·수도·가스 등)"},{"w":"荷物","m":"짐, 화물, 택배"},{"w":"予約","m":"예약"},{"w":"機械","m":"기계"},{"w":"大切","m":"소중함, 중요함"},{"w":"問題","m":"문제"},{"w":"食品ロス","m":"식품 폐기, 음식물 낭비"}],"grammar":[{"t":"〜ので","note":"원인이나 이유를 나타내며「から」보다 부드러운 느낌이에요. 예:「銀行のATMもあるので、いつでもお金をおろせます」"},{"t":"〜たり、〜たりする","note":"여러 가지 동작이나 일을 나열할 때 써요. 예:「公共料金をはらったり、荷物を送ったりもできます」"},{"t":"가능형(〜られる/〜える)","note":"「～할 수 있다」라는 뜻이에요. 예:「雑誌や日用品も買えます」「お金をおろせます」"},{"t":"〜ないで","note":"「～하지 않고 …하다」라는 뜻이에요. 예:「べんりさを当たり前だと思わないで、はたらく人のことも考えたいです」"}]},"a-n3-8-n2":{"title":"일본에서 병원에 갈 때의 순서","topic":"생활","trans":["일본에 와서 처음으로 열이 났을 때, 어떻게 대처해야 할지 몰라서 크게 불안했어요. 낯선 곳에서 몸이 안 좋으면 아픈 것 자체보다 막막한 마음이 더 커지기 쉬워요. 친구에게 상담했더니 「まず近くの内科に行ったほうがいいよ」라고 조언해 주었어요.","병원에서는 먼저 접수처에서 건강보험증을 내고 문진표에 증상을 적는 것이 일반적인 순서예요. 진료 때는 「いつから痛いですか」, 「アレルギーはありますか」 같은 질문을 받아요. 묻는 내용은 대체로 정해져 있으니 미리 답을 생각해 두면 당황하지 않아도 돼요.","진료가 끝나면 처방전을 받고, 그걸 가지고 약국에 가서 약을 받아요. 처음에는 단계가 많게 느껴질 수도 있지만, 한 번 해 보면 어렵지 않아요. 가장 신경 쓰이던 비용도 예상보다 훨씬 적게 들었어요. 건강보험에 가입되어 있으면 병원에서 본인이 내는 부담금은 30%로 끝나기 때문이에요.","언어에 자신이 없는 사람은 증상을 종이에 적어서 의사에게 보여 주면 좋아요. 의사를 전하는 방법이 말하기만 있는 것은 아니에요. 유창하게 말하지 못해도 전달할 방법은 얼마든지 있으니 지나치게 걱정할 필요는 없어요."],"vocab":["대처, 대응","막막하다, 불안하다","몸 상태가 나빠지다, 몸이 안 좋아지다","문진표","증상","당황하다","처방전","가입, 가입하다","본인 부담금","수단, 방법"],"grammar":[{"t":"〜たところ","note":"어떤 일을 한 뒤에 어떤 결과나 사실을 알게 되었음을 나타내요. 예: 「友達に相談したところ、『まず近くの内科に行ったほうがいいよ』とアドバイスをもらった」."},{"t":"〜といった","note":"예를 들 때 쓰며 '~ 같은'이라는 뜻이에요. 예: 「『いつから痛いですか』『アレルギーはありますか』といった質問をされる」."},{"t":"〜ずに済む","note":"어떤 일을 하지 않아도 해결되거나 나쁜 결과를 피했음을 나타내요. 예: 「事前に答えを考えておけば慌てずに済む」."},{"t":"〜とは限らない","note":"'반드시 ~인 것은 아니다'라는 뜻의 부분 부정이에요. 예: 「意思を伝える手段は、話すことだけとは限らない」."}]},"a-n3-8-n4":{"title":"일본에서 병원에 가기","topic":"생활","trans":["일본에서 처음으로 열이 났을 때, 어떻게 해야 할지 몰라서 불안했어요. 친구에게 물어보니 「近くの内科に行ったほうがいいよ」라고 했어요.","병원에서는 먼저 건강보험증을 내고 종이에 증상을 적어요. 「いつから痛いですか」나 「アレルギーはありますか」 같은 질문을 받아요. 진료가 끝나면 처방전이라는 종이를 받아요. 그 종이를 가지고 약국에 가서 약을 받아요.","병원비는 생각보다 쌌어요. 건강보험에 가입되어 있으면 본인이 내는 돈은 30%뿐이기 때문이에요. 말이 걱정되는 사람은 증상을 종이에 적어서 보여 주면 좋아요. 전달하는 방법은 많으니 걱정하지 않아도 괜찮아요."],"vocab":["열, 발열","불안","내과","건강보험증","증상","진찰, 진료","약국","받다, 수령하다","요금, 비용","전하다, 전달하다"],"grammar":[{"t":"〜たほうがいい","note":"조언할 때 쓰며 '~하는 편이 좋다'라는 뜻이에요. 예: 「近くの内科に行ったほうがいいよ」. 동사 た형에 붙어요."},{"t":"〜たら","note":"'~하고 나서' 또는 '~하면'이라는 뜻이에요. 예: 「診察が終わったら、処方箋という紙をもらいます」."},{"t":"〜ば(〜ていれば)","note":"'~하면'이라는 뜻의 조건을 나타내요. 예: 「保険に入っていれば、自分で払うのは三割だけだからです」."},{"t":"〜ので","note":"원인이나 이유를 나타내며 어감이 부드러워요. 예: 「伝える方法はたくさんあるので、心配しなくても大丈夫です」."}]},"a-n3-9-n2":{"title":"일본에서 방을 구할 때의 과정과 주의점","topic":"생활","trans":["일본에서 방을 빌리는 일은 많은 외국인이 생각하는 것보다 훨씬 손이 많이 가는 작업이에요. 먼저 부동산 중개소를 찾아가 월세 예산과 희망 지역을 담당자에게 전하는 것부터 절차가 시작돼요. '역에서 도보 10분 이내'라는 조건을 더하면 그에 따라 월세가 단번에 비싸져요.","마음에 드는 방을 찾았더라도 그 자리에서 바로 계약을 정할 수는 없어요. 시키킨(보증금), 레이킨(사례금), 중개 수수료 등 입주 시점에 목돈을 준비해야 하기 때문이에요. 외국인은 계약할 때 보증인을 요구받는 경우가 적지 않아요. 요즘은 보증인 대신 보증 회사를 이용하는 것이 일반적이어서, 월세의 절반 정도를 내고 계약해요.","심사를 통과하려면 근무처와 수입을 확인할 수 있는 서류를 미리 갖춰 두는 것이 좋아요. 방을 보러 갈 때는 채광이나 소음뿐 아니라 세탁기를 놓을 자리와 콘센트 개수까지 확인해 두고 싶어요. 사진으로는 알 수 없는 부분이야말로 직접 발걸음을 해서 보는 의미가 있다고 할 수 있어요.","이런 절차는 처음 겪는 사람에게는 번거롭게 느껴질 수 있어요. 하지만 미리 흐름을 알고 있는 것만으로도 준비의 부담이 크게 달라져요. 그래서 다음에 이사할 때는 이번보다 훨씬 수월하게 방을 구할 수 있을 거예요."],"vocab":[{"w":"不動産屋","m":"부동산 중개소, 부동산 회사"},{"w":"家賃","m":"월세, 집세"},{"w":"敷金","m":"보증금"},{"w":"礼金","m":"례금(집주인에게 주는 사례금)"},{"w":"仲介手数料","m":"중개 수수료"},{"w":"保証人","m":"보증인"},{"w":"審査","m":"심사"},{"w":"内見","m":"집 보기, 방 보러 가기"},{"w":"日当たり","m":"채광, 햇빛이 드는 정도"},{"w":"騒音","m":"소음"}],"grammar":[{"t":"〜に伴って","note":"어떤 일이 변하면 그에 따라 다른 일도 함께 변한다는 뜻이에요. 예: 「条件を加えると、それに伴って家賃は一気に高くなってしまう」"},{"t":"〜わけにはいかない","note":"도리나 상황상 그렇게 할 수 없다는 뜻이에요. 예: 「その場ですぐに契約を決めるわけにはいかない」"},{"t":"〜にあたって","note":"어떤 일을 할 때, 즈음이라는 뜻으로, 주로 격식 있는 자리에서 써요. 예: 「契約にあたって保証人を求められることが少なくない」"},{"t":"〜こそ","note":"앞의 말을 강조해서 '바로 이것'이라는 뜻을 나타내요. 예: 「写真ではわからない部分こそ、実際に足を運んで見る意味があるといえる」"}]},"a-n3-9-n4":{"title":"일본에서 방 구하기","topic":"생활","trans":["일본에서 방을 빌리는 일은 생각보다 손이 많이 가요. 먼저 부동산 중개소에 가서 월세 예산과 희망하는 지역을 이야기해요. 역에서 걸어서 10분 이내로 하면 월세가 꽤 비싸져요.","좋은 방을 찾더라도 바로 정할 수는 없어요. 시키킨(보증금), 레이킨(사례금), 중개 수수료 등 처음에 돈이 많이 필요하기 때문이에요. 외국인은 보증인이 필요하다는 말을 듣는 경우가 많아요. 요즘은 보증 회사를 이용하는 사람이 많고, 월세의 절반 정도를 내고 계약해요. 심사를 통과할 수 있도록 일과 수입을 알 수 있는 서류를 준비해 두면 좋아요.","사진으로는 알 수 없으니 채광이나 소리를 직접 가서 확인하면 좋아요. 세탁기를 놓을 자리와 콘센트 개수도 봐 두는 것이 좋아요. 힘들어 보이지만 이 과정을 알고 있으면 다음 이사는 수월해져요."],"vocab":[{"w":"部屋","m":"방"},{"w":"手間","m":"수고, 품, 번거로움"},{"w":"不動産屋","m":"부동산 중개소, 부동산 회사"},{"w":"家賃","m":"월세, 집세"},{"w":"予算","m":"예산"},{"w":"保証人","m":"보증인"},{"w":"契約","m":"계약"},{"w":"書類","m":"서류"},{"w":"準備","m":"준비"},{"w":"確認","m":"확인"}],"grammar":[{"t":"〜ても","note":"'~해도, ~하더라도'라는 뜻이에요. 예: 「いい部屋が見つかっても、すぐには決められない」"},{"t":"〜ように","note":"어떤 목적이나 결과를 이루기 위해서라는 뜻이에요. 예: 「審査に通るように、仕事と収入がわかる書類を準備しておくといい」"},{"t":"〜ておく","note":"미리 준비해 둔다는 뜻이에요. 예: 「書類を準備しておくといい」「見ておいたほうがいい」"},{"t":"〜たほうがいい","note":"'~하는 편이 좋다'는 뜻으로, 조언할 때 써요. 예: 「コンセントの数も、見ておいたほうがいい」"}]},"a-n4-2-n2":{"title":"전철 안의 매너와 일본인의 사고방식","topic":"생활","trans":["일본 전철 안은 대화 소리가 거의 들리지 않을 만큼 조용해요. 승객 대부분은 책을 읽거나 스마트폰을 보거나 눈을 감고 쉬면서 저마다 편한 대로 시간을 보내요. 모두 주변을 살피면서 각자 자기만의 시간을 조용히 즐기고 있는 거예요.","특히 전철 안에서 전화를 하는 행위는 일반적으로 매너 위반으로 여겨져요. 꼭 통화해야 할 때는 일단 전철에서 내린 다음에 걸 수밖에 없어요. 또 노약자석 근처에서는 휴대전화 전원을 끄도록 요청받는 경우도 있어요. 심박 조율기 같은 의료기기에 영향을 줄 우려가 있기 때문이에요.","이런 매너의 배경에는 '주변 사람에게 폐를 끼치지 않는다'라는 일본인의 사고방식이 있어요. 명문화된 규칙이라기보다는 서로를 배려하는 마음에서 나온 습관이라고 할 수 있어요. 내 행동이 주변에 어떤 영향을 줄지 상상해 보는 것이 이 사고방식의 출발점이에요.","이런 매너는 많은 사람이 기분 좋게 전철을 이용하는 데 꼭 필요해요. 자신의 사정만 앞세우지 않고 주변 사람도 생각하며 행동하는 것이 중요해요. 그러면 모두가 쾌적하게 지낼 수 있는 공간이 지켜져요."],"vocab":["저마다 생각대로, 각자 마음 가는 대로","주위, 주변 사람들","위반","~로 여겨지다, ~로 간주되다","전원","~할 우려, ~할 가능성","배경","폐, 민폐","명문화, 글로 규정함","빼놓을 수 없는, 꼭 필요한"],"grammar":[{"t":"〜ざるを得ない","note":"어쩔 수 없이 해야 한다, 다른 선택지가 없다는 뜻이에요. 예: 「どうしても話したいときは、いったん電車を降りてからかけざるを得ません」"},{"t":"〜というより","note":"'~라기보다는 ~'라는 뜻으로, 표현을 바로잡을 때 써요. 예: 「明文化されたルールというより、お互いへの思いやりに基づいた習慣だと言えます」"},{"t":"〜おそれがある","note":"좋지 않은 일이 일어날 가능성이 있다는 뜻이며, 주로 문어체에서 써요. 예: 「ペースメーカーなどの医療機器に影響を与えるおそれがあるからです」"},{"t":"〜に基づく","note":"'~을 바탕으로', '~에 근거해'라는 뜻이에요. 예: 「お互いへの思いやりに基づいた習慣だと言えます」"}]},"a-n4-2-n3":{"title":"전철 안의 매너","topic":"생활","trans":["일본 전철 안은 다른 나라와 비교하면 아주 조용하다고들 해요. 많은 사람이 책을 읽거나 스마트폰을 보거나 눈을 감고 쉬면서 시간을 보내요.","전철 안에서 전화를 하는 것은 매너 위반이라고 여겨져요. 꼭 통화해야 할 때는 역에서 전철을 내린 뒤에 거는 것이 보통이에요. 또 노약자석 근처에서는 휴대전화 전원을 꺼 달라고 요청받는 경우도 있어요. 심박 조율기 같은 의료기기에 영향을 줄지도 모르기 때문이에요.","이런 매너의 배경에는 '주변 사람에게 폐를 끼치지 않는다'라는 일본의 사고방식이 있어요. 규칙이라서 지킨다기보다는 서로를 배려하는 마음에서 지켜지고 있는 거예요. 이처럼 조용한 객실은 주변에 대한 배려로 만들어지는 거예요.","이런 매너는 많은 사람이 기분 좋게 전철을 이용하기 위한 거예요. 자신만이 아니라 주변 사람도 생각하며 행동하면 모두가 쾌적하게 지낼 수 있을 거예요."],"vocab":["위반, 어김","노약자석(우선석)","전원","의료기기","영향","배경","폐, 민폐","배려, 헤아리는 마음","마음씀, 배려","쾌적함"],"grammar":[{"t":"〜ように(부탁·요구)","note":"부탁이나 요구의 내용을 나타내요. 예: 「携帯電話の電源を切るようにお願いされる場合もあります」"},{"t":"〜というより","note":"'~라기보다는 ~'라는 뜻이에요. 예: 「ルールだからというより、お互いへの思いやりから守られているのです」"},{"t":"〜によって","note":"원인, 수단, 근거를 나타내요. 예: 「周りへの気づかいによって作られているのです」"},{"t":"〜ための+名詞","note":"목적을 나타내며 뒤의 명사를 꾸며 줘요. 예: 「たくさんの人が気持ちよく電車を利用するためのものです」"}]},"a-n3-12-n2":{"title":"비즈니스 메일의 기본 매너","topic":"직장","trans":["일본 회사에서 일하려면 메일 작성의 기본 규칙을 알아 두는 것이 꼭 필요해요. 메일은 전화와 달리 상대가 편한 시간에 읽을 수 있다는 장점이 있지만, 반면에 쓰는 방식에 따라서는 실례가 되는 인상을 줄 수도 있어요. 그래서 신입 사원은 선배가 쓰는 방식을 잘 보고 조금씩 익혀 가는 것이 일반적이에요.","먼저 제목은 한눈에 내용을 알 수 있도록 간결하게 쓰는 것이 중요해요. 「会議の件」만으로는 부족하고, 「来週の会議の日程について」처럼 구체적으로 쓰는 편이 더 잘 전달돼요. 제목이 알아보기 어려우면 상대가 바쁠 때 메일을 놓칠 우려가 있어요. 그렇다고 해서 제목이 길수록 좋은 것은 아니고, 짧게 정리하는 요령도 필요해요.","첫머리에는 「お世話になっております」라는 인사말을 자주 써요. 이는 상대와의 관계에 대한 감사를 나타내는 표현으로, 사외 사람에게도 사내 사람에게도 쓸 수 있어요. 처음 연락하는 상대에게는 「はじめてご連絡いたします」 같은 표현을 쓰기도 해요. 본문에서는 용건이 정확하게 전달되도록 짧은 문장으로 정중하게 쓰는 것이 요구돼요.","마지막은 「よろしくお願いいたします」라는 말로 마무리하는 사람이 많아요. 이 한마디만 있어도 글 전체가 정중한 인상이 되고, 상대도 기분 좋게 읽어 내려갈 수 있어요. 또 메일을 받으면 되도록 빨리 답장하는 것도 중요한 매너 중 하나예요. 바로 답을 주지 못하는 경우에도 「確認して後日ご連絡します」라고 한마디 보내 두면 상대는 안심할 수 있을 거예요."],"vocab":["빠뜨릴 수 없는, 꼭 필요한","사정, 형편(편한 때)","인상","간결함","놓치다, 못 보고 지나치다","궁리, 연구, 요령","용건, 볼일","요구되다, 기대되다","마무리하다, 끝맺다","답장"],"grammar":[{"t":"〜うえで","note":"「어떤 일을 하는 과정/측면에서」를 나타내며, 뒤에는 중요하거나 필요한 내용이 자주 와요. 예: 「日本の会社で働くうえで、メールの書き方の基本的なルールを知っておくことは欠かせません」"},{"t":"〜反面","note":"같은 일에 서로 반대되는 두 면이 함께 있음을 나타내요. 「~한 반면에 …」. 예: 「相手の都合のよい時間に読んでもらえる反面、書き方次第では失礼な印象を与えかねません」"},{"t":"〜かねない","note":"동사의 ます형에서 ます를 뗀 형태에 붙어 「나쁜 결과가 생길 수도 있다」는 뜻을 나타내요. 예: 「書き方次第では失礼な印象を与えかねません」"},{"t":"〜とは限らない","note":"「반드시 ~인 것은 아니다」라는 뜻으로, 지나치게 단정적인 생각을 부정해요. 예: 「件名は長ければ長いほどよいとは限らず、短くまとめる工夫も必要です」"}]},"a-n3-12-n4":{"title":"비즈니스 메일의 기본","topic":"직장","trans":["일본 회사에서 일할 때 메일을 쓰는 데에는 몇 가지 기본 규칙이 있어요. 메일은 상대가 편한 시간에 읽을 수 있어서 편리해요. 쓰는 방식을 잘못하면 실례라고 여겨질 수 있어서, 신입 사원은 선배에게 배워요.","먼저 제목은 한눈에 내용을 알 수 있도록 짧게 쓰는 것이 중요해요. 「会議の件」이 아니라 「来週の会議の日程について」라고 쓰면 좋아요. 제목을 알아보기 어려우면 바쁜 상대는 메일을 읽지 않을지도 몰라요.","메일 첫머리에는 「お世話になっております」라는 말을 자주 써요. 이것은 감사한 마음을 전하는 말로, 사외 사람에게도 사내 사람에게도 쓸 수 있어요. 메일 마지막은 「よろしくお願いいたします」로 끝내는 사람이 많아요. 메일을 받으면 되도록 빨리 답장하는 것도 중요한 매너예요. 바로 대답할 수 없을 때도 「確認してあとで連絡します」라고 보내면 안심이 돼요."],"vocab":["(메일의) 제목","일정","중요함","실례, 무례함","신입 사원","(시간상의) 형편, 사정","감사","사외, 회사 밖","답장, 대답","안심"],"grammar":[{"t":"〜ので","note":"원인이나 이유를 나타내며, 어감이 비교적 부드러워요. 예: 「相手が都合のいい時間に読めるので便利です」"},{"t":"〜ように","note":"「~하도록」이라는 목적이나 상태를 나타내요. 예: 「一目で内容がわかるように、短く書くことが大切です」"},{"t":"〜と(조건)","note":"「~하면」이라는 뜻으로, 뒤에는 결과나 제안이 자주 와요. 예: 「件名がわかりにくいと、忙しい相手はメールを読まないかもしれません」"},{"t":"〜たら","note":"「~하면, 일단 ~하고 나면」이라는 뜻으로, 어떤 일을 한 뒤의 행동을 설명할 때 써요. 예: 「メールをもらったら、できるだけ早く返事をするのも大切なマナーです」"}]},"a-n4-8-n2":{"title":"구청에서 하는 수속 절차","topic":"생활","trans":["일본에서는 이사를 하면 14일 이내에 구청에 가서 주소와 관련된 신고를 해야 해요. 저는 창구에서 「転入届を出したいのですが」라고 말하고 번호표를 받았어요. 번호표를 나눠 주는 것은 순서대로 응대하기 위한 방식으로, 이용자가 많은 시간대에도 혼란이 생기기 어렵게 되어 있어요.","이름이 불릴 때까지는 의자에 앉아서 기다릴 수밖에 없지만, 그동안 서류에 주소와 생년월일을 미리 적어 두었어요. 차례가 되어 창구에 가자, 담당 직원이 재류카드를 확인하고 뒷면에 새 주소를 써 주었어요. 재류카드는 신분을 증명하는 중요한 카드이기 때문에 새 주소가 정확하게 기재되어 있는 것이 중요해요.","같은 날 국민건강보험 수속도 마칠 수 있지만, 담당 창구가 달라서 1층에서 2층으로 이동했어요. 수속 종류에 따라 창구가 나뉘어 있는 것은 익숙해지기 전에는 조금 번거롭게 느껴질 수도 있어요. 모두 끝나기까지 한 시간 정도 걸렸지만, 생각했던 것보다 순조롭게 진행된 느낌이에요. 게다가 일본어만으로 수속을 마칠 수 있었다는 사실에, 앞으로도 여기서 살아갈 수 있겠다는 자신감이 조금 생겼어요.","모르는 것이 있으면 망설이지 말고 질문하는 편이 좋다고 생각해요. 외국인 이용자에게도 담당 직원이 천천히 친절하게 말해 주기 때문에, 다시 물어보는 것을 주저할 필요는 없어요. 일본어에 자신이 없다고 해서 창구 수속이 반드시 어려운 것은 아니에요. 하나씩 확인하면서 진행하면 필요한 수속은 침착하게 마칠 수 있을 거예요."],"vocab":[{"w":"届け出","m":"신고"},{"w":"窓口","m":"창구"},{"w":"番号札","m":"번호표"},{"w":"仕組み","m":"방식, 구조"},{"w":"記入","m":"기입, 적어 넣음"},{"w":"裏面","m":"뒷면"},{"w":"証明","m":"증명"},{"w":"担当","m":"담당"},{"w":"異なる","m":"다르다"},{"w":"ためらう","m":"망설이다, 주저하다"}],"grammar":[{"t":"〜に伴って","note":"'~에 따라, ~와 함께'라는 뜻으로, 앞의 변화에 맞춰 뒤의 일이 일어날 때 써요. 예: 「引っ越しに伴って、十四日以内に区役所へ行き」"},{"t":"〜ざるを得ない","note":"'~할 수밖에 없다'라는 뜻으로, 다른 선택지가 없을 때 써요. 예: 「椅子に座って待たざるを得ませんが」"},{"t":"〜に対して","note":"'~에게, ~에 대해'라는 뜻으로, 행동이나 태도가 향하는 대상을 나타내요. 예: 「外国人の利用者に対しても、係の人はゆっくり丁寧に話してくれる」"},{"t":"〜とは限らない","note":"'반드시 ~인 것은 아니다'라는 뜻으로, '당연히 ~일 것'이라는 생각을 부정할 때 써요. 예: 「窓口での手続きが難しいとは限りません」"}]},"a-n4-8-n3":{"title":"구청에서 하는 수속","topic":"생활","trans":["이사를 하면 14일 이내에 구청에 가서 주소를 변경하는 수속을 해야 해요. 제가 창구에서 「転入届を出したいのですが」라고 말하자 번호표를 받았어요. 이름이 불릴 때까지 의자에 앉아 기다렸고, 그동안 서류에 주소와 생년월일을 적어 두었어요.","차례가 되자 담당 직원이 제 재류카드를 확인한 다음 뒷면에 새 주소를 써 주었어요. 같은 날 국민건강보험 수속도 할 수 있어서 이어서 하기로 했어요. 다만 창구가 달라서 1층에서 2층으로 이동해야 했어요.","모두 끝나기까지 한 시간쯤 걸렸어요. 그래도 일본어만으로 수속을 할 수 있어서 자신감이 조금 생겼어요.","모르는 것이 있으면 망설이지 말고 담당 직원에게 물어보는 편이 좋다고 생각해요. 담당 직원이 우리가 알아들을 수 있도록 천천히 말해 주기 때문이에요."],"vocab":[{"w":"手続き","m":"수속, 절차"},{"w":"窓口","m":"창구"},{"w":"転入届","m":"전입 신고"},{"w":"番号札","m":"번호표"},{"w":"書類","m":"서류"},{"w":"在留カード","m":"재류카드"},{"w":"確認","m":"확인"},{"w":"移動","m":"이동"},{"w":"自信","m":"자신감"},{"w":"遠慮","m":"사양, 망설임"}],"grammar":[{"t":"〜ことにする","note":"스스로 어떤 일을 하기로 결정했을 때 써요. 예: 「続けて行うことにしました」(이어서 하기로 했어요)"},{"t":"〜ため(原因・理由)","note":"원인이나 이유를 조금 격식 있게 나타내요. 예: 「窓口が違うため、一階から二階へ移動しなければなりませんでした」"},{"t":"〜ように","note":"목적을 나타내며, 어떤 상태가 되도록 한다는 뜻이에요. 예: 「こちらが分かるようにゆっくり話してくれる」(우리가 알아들을 수 있도록 천천히 말해 줘요)"},{"t":"受け身形(〜れる・〜られる)","note":"다른 사람에게 어떤 일을 당하거나 받는다는 뜻을 나타내요. 예: 「番号札を渡されました」「名前を呼ばれるまで」"}]},"a-n4-9-n2":{"title":"치과에 다니면서 깨달은 것","topic":"생활","trans":["3일 전부터 이가 아프기 시작했지만 그냥 둘 수도 없어서 집 근처 치과에 예약했어요. 접수처에서 보험증을 제시하자 먼저 문진표를 작성해 달라고 했어요. 통증이 언제부터 시작됐는지, 차가운 것을 먹으면 시린지 같은 항목에 차례로 답했어요.","진료 결과, 의사 선생님은 \"충치가 하나 있네요\"라고 말하며 엑스레이 사진을 보여 주면서 상태를 설명해 주셨어요. 오늘은 患部만 깎아 내고 약을 넣는 데서 그치고, 다음 주에 한 번 더 내원하라고 하셨어요. 원인을 알게 돼서 안심했지만, 한 번으로는 치료가 끝나지 않는다는 말을 듣고 조금 아쉬운 기분이 들었어요.","치료가 끝난 뒤에는 양치질하는 방법에 대해서도 지도를 받았어요. 힘을 주어 너무 세게 닦으면 오히려 잇몸을 상하게 할 수 있다고 해요. 매일 아무렇지 않게 하던 습관이 사실은 역효과를 낼 수도 있다는 걸 알고 놀랐어요.","일본 치과는 여러 번 다닐 수밖에 없지만, 그만큼 한 번 한 번의 치료가 꼼꼼하게 이루어져요. 다니는 수고가 분명 크기는 하지만, 꼼꼼한 치료에는 무엇과도 바꿀 수 없는 가치가 있다고 느꼈어요. 이번 경험으로 아파지고 나서 허둥지둥 달려가는 게 아니라 증상이 나타나기 전에 행동해야 한다는 걸 절실히 깨달았어요. 적어도 반년에 한 번은 검진을 받는 것이 아픈 일을 겪지 않기 위한 최선의 방법이라고 생각해요."],"vocab":["그냥 두다, 방치하다","건강보험증, 보험증","제시","문진표","환부, 아픈 부위","지도","상하게 하다, 다치게 하다","역효과","통원, 병원에 다님","절실히 느낌, 통감"],"grammar":[{"t":"〜ものの","note":"'~이지만, ~하긴 했지만'이라는 뜻으로, 앞뒤 내용이 대조돼요. 예: 「三日前から歯が痛み始めたものの、放っておくわけにもいかず」."},{"t":"〜かねない","note":"동사의 ます형에서 ます를 뺀 형태에 붙어 '(좋지 않은 일이) 일어날 수도 있다'는 뜻이에요. 예: 「実は逆効果になりかねないと知り」."},{"t":"〜ざるを得ない","note":"'~할 수밖에 없다, 어쩔 수 없이 ~하다'라는 뜻으로, 마지못해 하는 뉘앙스가 있어요. 예: 「何度も通院せざるを得ませんが」."},{"t":"〜とはいえ","note":"'~라고는 하지만, 그렇다 해도'라는 뜻으로, 앞의 내용을 인정한 뒤 뒤에서 자기 생각을 말해요. 예: 「通う手間は確かに大きいとはいえ」."}]},"a-n4-9-n3":{"title":"치과에 간 날","topic":"생활","trans":["3일 전부터 이가 아프기 시작해서 집 근처 치과에 예약했어요. 접수처에서 보험증을 내자 문진표를 작성하라고 했어요. 언제부터 아픈지, 차가운 것을 먹으면 시린지 같은 것을 적었어요.","의사 선생님은 \"충치가 하나 있네요\"라고 말하며 엑스레이 사진을 보여 주셨어요. 오늘은 충치를 깎고 약을 넣기만 하고, 다음 주에 한 번 더 오라고 하셨어요.","치료가 끝난 뒤에는 양치질하는 방법도 알려 주셨어요. 힘을 주어 너무 세게 닦으면 잇몸을 상하게 할 때가 있다고 해요. 매일 하는 양치질에도 올바른 방법이 있다는 걸 알게 됐어요.","일본 치과는 여러 번 다녀야 해요. 하지만 그만큼 한 번 한 번 꼼꼼하게 치료해 주기 때문에 안심이 돼요. 아파지고 나서 허둥대기보다 반년에 한 번은 검진을 받으러 가는 게 좋겠다고 생각했어요. 앞으로는 일찍 치과에 가기로 했어요."],"vocab":["예약","접수처","기입, 작성","문진표","충치","깎다","상하게 하다, 다치게 하다","꼼꼼함, 정중함","허둥대다, 당황하다","검진"],"grammar":[{"t":"〜ように言われる","note":"어떤 일을 하라고 요구받거나 지시받았다는 뜻이에요. 지시 내용을 간접적으로 전달할 때 써요. 예: 「問診票に記入するように言われました」"},{"t":"〜について","note":"'~에 대해, ~에 관해'라는 뜻으로, 화제를 꺼낼 때 써요. 예: 「歯みがきの仕方についても教えてもらいました」"},{"t":"〜ぶん","note":"'그만큼'이라는 뜻으로, 앞의 상황 때문에 그에 상응하는 이점이나 결과가 있음을 나타내요. 예: 「そのぶん一回ずつ丁寧に治療してくれる」"},{"t":"〜ことにする","note":"스스로 어떤 일을 하기로 결심했다는 뜻이에요. 예: 「これからは早めに歯医者へ行くことにします」"}]},"a-n4-11-n2":{"title":"전철에 우산을 두고 내린 날","topic":"생활","trans":["오늘 저는 깜빡하고 전철 안에 우산을 두고 내리는 실수를 했어요. 알아챘을 때는 전철이 이미 다음 역에 도착해 있었고, 우산은 이미 제 손에 없었어요. 어찌할 바를 몰랐지만, 일단 역 분실물 센터에 가서 상담해 보기로 했어요.","창구 직원에게 우산을 잃어버린 경위를 순서대로 설명했어요. 직원이 \"특징을 알려 주세요\"라고 해서 먼저 색과 모양을 말하기로 했어요. \"검은색이고 손잡이가 조금 휘어 있는 우산이에요\"라고 구체적으로 말했어요. 그러자 직원은 \"잠시만 기다려 주세요, 찾아볼게요\"라고 하더니 바로 찾으러 가 주었어요.","잠시 기다리자 비슷한 우산이 발견될 것 같다는 연락이 왔어요. 안쪽에서 우산을 가져와 달라고 해서 확인해 보니, 그것은 틀림없는 제 우산이었어요. 그 자리에서 바로 우산을 돌려받을 수 있어서 진심으로 안심했어요. 한때는 포기할 뻔했던 만큼 안도감이 남달랐어요.","이번 경험을 통해 조심하고 있어도 물건을 두고 내리는 일은 일어날 수 있다는 것을 절실히 느꼈어요. 앞으로는 전철에서 내릴 때 두고 내리는 물건이 없는지 꼭 확인하려고 해요. 작은 습관이지만 이를 게을리하지 않는 것이 같은 실수를 막는 가장 좋은 방법이라고 생각해요."],"vocab":["도착, 도착하다","손 닿는 곳, 手元(수중·곁)","어찌할 바를 모르다, 막막하다","경위, 자초지종","순서대로","틀림없이, 분명히","유독, 한층 더","절실히 느낌, 통감","명심하다, 유념하다","게을리하다, 소홀히 하다"],"grammar":[{"t":"〜たところ","note":"어떤 행동을 한 뒤에 어떤 결과를 알게 되었음을 나타내요. 뒤에는 확인된 사실이 주로 와요. 예: 「奥から傘を持ってきてもらって確認したところ、それはまぎれもなく私の傘でした」."},{"t":"〜だけに","note":"앞의 상황 때문에 뒤의 감정이나 결과가 유독 강하다는 뜻이에요. '~했던 만큼'에 해당해요. 예: 「一時はあきらめかけていただけに、安心感はひとしおでした」."},{"t":"〜を通じて","note":"어떤 경험이나 수단을 통해 어떤 결과를 얻음을 나타내요. '~을 통해'에 해당해요. 예: 「今回の経験を通じて、忘れ物は気をつけていても起こり得ることだと痛感しました」."},{"t":"〜かける","note":"동사 ます형에 붙어 동작이 도중이거나 막 하려는 상태임을 나타내요. '~하다 말다', '~할 뻔하다'에 해당해요. 예: 「一時はあきらめかけていただけに」."}]},"a-n4-11-n3":{"title":"전철에 우산을 두고 내린 날","topic":"생활","trans":["오늘 전철 안에 우산을 두고 내려서 너무 당황했어요. 전철이 다음 역에 도착했을 때에야 비로소 우산이 없다는 걸 알아챘어요. 어떻게 해야 할지 망설였지만, 역 분실물 센터에 가서 문의하기로 했어요.","직원에게 전철 안에서 우산을 잃어버렸다고 설명했어요. 그러자 \"우산의 특징을 알려 주시겠어요?\"라고 물어서 색과 모양을 말했어요. \"검은색이고 손잡이가 조금 휘어 있는 우산이에요\"라고 최대한 자세히 말했어요. 직원은 \"잠시만 기다려 주세요, 찾아볼게요\"라고 하고는 안쪽으로 찾으러 가 주었어요.","잠시 기다리자 비슷한 우산을 찾은 것 같다고 알려 주었어요. 안쪽에서 가져다준 우산을 보니 분명 제 우산이었어요. 바로 돌려받을 수 있어서 정말 안심했어요. 앞으로는 전철에서 내릴 때 두고 내리는 물건이 없는지 확인하려고 해요."],"vocab":["물건을 어딘가에 두고 잊어버리다","당황하다, 허둥대다","알아채다, 깨닫다","상담, 문의","담당 직원","특징","(우산 등의) 손잡이","휘다, 구부러지다","받다, 수령하다","확인, 확인하다"],"grammar":[{"t":"〜ことにする","note":"스스로 어떤 일을 하기로 결정했음을 나타내요. 예: 「忘れ物センターへ行って相談することにしました」(분실물 센터에 가서 문의하기로 했어요)."},{"t":"〜ようだ","note":"상황을 근거로 한 추측이나 전해 들은 내용을 나타내요. '~인 것 같다'에 해당해요. 예: 「似ている傘が見つかったようだと教えてもらいました」(비슷한 우산이 발견된 것 같다고 알려 주었어요)."},{"t":"〜てもらう","note":"다른 사람에게 부탁해서 어떤 일을 해 받거나 도움을 받음을 나타내요. 예: 「奥から持ってきてもらった傘を見ると」(안쪽에서 가져다준 우산을 보니)."},{"t":"〜ようにする","note":"어떤 습관을 들이려 노력하거나 가능한 한 그렇게 하려고 함을 나타내요. 예: 「忘れ物がないか確認するようにしようと思います」(두고 내리는 물건이 없는지 확인하려고 해요)."}]},"a-n4-6":{"title":"여름 축제","topic":"문화","trans":["일본의 여름에는 여기저기에서 여름 축제가 열려요. 밤이 되면 많은 사람이 유카타를 입고 신사나 절에 모여요.","축제 장소에는 노점이 많이 늘어서 있어요. 다코야키나 빙수를 먹기도 하고 금붕어 건지기를 하기도 하면서 모두 즐거워 보여요.","밤이 끝날 무렵에는 커다란 불꽃놀이가 펼쳐져요. 쾅 하는 큰 소리가 나고 밤하늘에 빛이 퍼지면 모두 「わあ」 하고 탄성을 질러요.","여름 축제는 일본 여름의 소중한 추억이 되는 행사예요. 기회가 있다면 꼭 유카타를 입고 가 보세요."],"vocab":["여름 축제","열다, 개최하다","유카타(여름 전통 의상)","신사","노점, 포장마차","늘어서다","금붕어 건지기","불꽃놀이","밤하늘","행사","기회"],"grammar":[{"t":"〜たり〜たりする","note":"여러 동작을 나열할 때 써요: 食べたり、すくいをしたり."},{"t":"〜と(자연스러운 결과)","note":"「光が広がると」처럼 '~하면'이라는 뜻으로, 자연스럽게 이어지는 결과를 나타내요."},{"t":"〜てみてください","note":"「行ってみてください」처럼 '~해 보세요'라는 뜻으로, 한번 시도해 보라고 권할 때 써요."}]},"a-n3-7":{"title":"열사병에 조심하세요","topic":"생활","trans":["최근 몇 년 사이 일본의 여름은 점점 더 더워지고 있어요. 특히 7월부터 8월 사이에는 기온이 35도를 넘는 날도 드물지 않아요.","이런 무더위 속에서 꼭 조심해야 할 것이 바로 열사병이에요. 몸에 수분이 부족해지면 어지럼증이나 두통이 생기고, 심하면 생명이 위험해질 수도 있어요.","열사병을 예방하려면 목이 마르기 전에 물을 자주 마시는 것이 중요해요. 더운 시간대에는 외출을 피하고 에어컨을 잘 활용하는 것도 좋은 방법이에요.","'나는 아직 괜찮아'라고 생각하는 사이에 몸 상태가 나빠지는 경우도 적지 않아요. 주변 사람들과 서로 말을 걸어 챙겨 주면서 무더운 여름을 건강하게 이겨 내요."],"vocab":["최근 몇 년","열사병","기온","넘다","수분","두통","생명, 목숨","관계되다, 달려 있다","예방하다, 막다","시간대","외출","몸 상태, 컨디션","극복하다, 이겨 내다"],"grammar":[{"t":"〜から〜にかけて","note":"「七月から八月にかけて」처럼 대략적인 기간이나 범위를 나타내요."},{"t":"〜うちに","note":"「思っているうちに」처럼 ~하는 상태가 계속되는 동안(어느새 ~하게 됨)을 나타내요."},{"t":"〜なければならない","note":"「気をつけなければならない」처럼 의무, 반드시 해야 한다는 뜻을 나타내요."}]}};
